// Teoribok: GFYS (Grunnleggende fysikk), MEK1400, MATS2100, FLUID, VARME

// ================= GFYS – enhet 0: Størrelser, enheter og måling =================
TOPICS("GFYS", 0, [
{ id: "si-enheter",
  nb: { t: "SI-enheter",
    intro: "En fysisk størrelse er alltid et tall ganger en enhet. SI-systemet har sju grunnenheter (meter, kilogram, sekund, ampere, kelvin, mol og candela), og de fleste andre enhetene er bygd opp av disse. En enhetsfeil gjør et ellers riktig regnestykke ubrukelig, så sjekk alltid at enheten i svaret stemmer.",
    f: [["1\\ \\mathrm{N} = 1\\ \\mathrm{kg\\cdot m/s^2}", "kraft, fra Newtons 2. lov"], ["1\\ \\mathrm{J} = 1\\ \\mathrm{N\\cdot m}", "energi og arbeid"], ["1\\ \\mathrm{W} = 1\\ \\mathrm{J/s}", "effekt"]],
    legend: [["m", "meter, grunnenhet for lengde", ""], ["kg", "kilogram, grunnenhet for masse", ""], ["s", "sekund, grunnenhet for tid", ""]],
    ex: "En last har massen $m = 250$ kg. Tyngden er $G = mg = 250\\cdot 9{,}81 \\approx 2453$ N, altså omtrent $2{,}45$ kN – en kraft, ikke en masse.",
    tip: "Skriv alltid enheten sammen med tallet i hvert mellomsteg – uten enhet er et tall meningsløst i fysikk." },
  en: { t: "SI units",
    intro: "A physical quantity is always a number times a unit. The SI system has seven base units (meter, kilogram, second, ampere, kelvin, mole and candela), and most other units are built from these. A unit error makes an otherwise correct calculation useless, so always check that the unit of your answer makes sense.",
    f: [["1\\ \\mathrm{N} = 1\\ \\mathrm{kg\\cdot m/s^2}", "force, from Newton's second law"], ["1\\ \\mathrm{J} = 1\\ \\mathrm{N\\cdot m}", "energy and work"], ["1\\ \\mathrm{W} = 1\\ \\mathrm{J/s}", "power"]],
    legend: [["m", "meter, base unit of length", ""], ["kg", "kilogram, base unit of mass", ""], ["s", "second, base unit of time", ""]],
    ex: "A load has mass $m = 250$ kg. Its weight is $G = mg = 250\\cdot 9.81 \\approx 2453$ N, about $2.45$ kN – a force, not a mass.",
    tip: "Always write the unit together with the number at every step – without a unit, a number is meaningless in physics." } },
{ id: "prefikser-omregning",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 115H220" class="dim"/><path d="M40 115v-8M80 115v-8M120 115v-8M160 115v-8M200 115v-8" class="dim"/><text x="30" y="132">n</text><text x="70" y="132">µ</text><text x="110" y="132">m</text><text x="150" y="132">1</text><text x="190" y="132">k</text><path d="M50 60H190" class="a"/><path d="M190 60l-12-5v10z" class="af"/><path d="M50 60l12-5v10z" class="af"/><text x="105" y="50">10³</text></svg>`,
  nb: { t: "Prefikser og omregning",
    intro: "Prefikser som kilo, milli og mikro er tierpotenser foran en enhet, og gjør at vi slipper å skrive svært store eller små tall. Før du setter tall inn i en formel, må du regne alt om til SI-grunnenheter: meter, kilogram og sekund, ikke km, gram eller minutter.",
    f: [["1\\ \\mathrm{km/h} = \\dfrac{1}{3{,}6}\\ \\mathrm{m/s}", "fart om til SI"], ["1\\ \\mathrm{m^2} = 10^4\\ \\mathrm{cm^2}", "areal skaleres med kvadratet av lengdefaktoren"], ["1\\ \\mathrm{m^3} = 1000\\ \\mathrm{L}", "volum, siden 1 L = 1 dm³"]],
    legend: [["k", "kilo-prefiks, tusen ganger", ""], ["m", "milli-prefiks, tusendel", ""], ["\\mu", "mikro-prefiks, milliondel", ""]],
    ex: "En bil kjører i $90$ km/h. I SI blir det $90/3{,}6 = 25$ m/s. En tank rommer $2{,}0$ m³ olje, altså $2{,}0\\cdot 1000 = 2000$ L.",
    tip: "Gang eller del med en brøk lik 1, for eksempel $1000\\ \\mathrm{m}/1\\ \\mathrm{km}$, for å bytte enhet uten å gjøre feil." },
  en: { t: "Prefixes and conversion",
    intro: "Prefixes such as kilo, milli and micro are powers of ten placed in front of a unit, so we avoid writing very large or very small numbers. Before you substitute numbers into a formula, convert everything to SI base units: meters, kilograms and seconds, not km, grams or minutes.",
    f: [["1\\ \\mathrm{km/h} = \\dfrac{1}{3.6}\\ \\mathrm{m/s}", "speed converted to SI"], ["1\\ \\mathrm{m^2} = 10^4\\ \\mathrm{cm^2}", "area scales with the square of the length factor"], ["1\\ \\mathrm{m^3} = 1000\\ \\mathrm{L}", "volume, since 1 L = 1 dm³"]],
    legend: [["k", "kilo prefix, times a thousand", ""], ["m", "milli prefix, a thousandth", ""], ["\\mu", "micro prefix, a millionth", ""]],
    ex: "A car drives at $90$ km/h. In SI that is $90/3.6 = 25$ m/s. A tank holds $2.0$ m³ of oil, which is $2.0\\cdot 1000 = 2000$ L.",
    tip: "Multiply or divide by a fraction equal to 1, for example $1000\\ \\mathrm{m}/1\\ \\mathrm{km}$, to change units without making mistakes." } },
{ id: "gjeldende-siffer",
  nb: { t: "Gjeldende siffer",
    intro: "Gjeldende siffer er sifrene i et tall som bærer faktisk informasjon om hvor nøyaktig målingen er. Ledende nuller teller ikke, mens nuller mellom andre sifre og nuller bakerst etter komma gjør det. Et svar kan aldri være mer nøyaktig enn de tallene det er regnet ut fra.",
    f: [["\\text{Ganging/deling: færrest siffer bestemmer}", "svaret rundes til like mange gjeldende siffer som den minst nøyaktige faktoren"], ["4{,}05 \\to 3\\ \\text{siffer}", "nuller mellom sifre teller"], ["0{,}0052 \\to 2\\ \\text{siffer}", "ledende nuller teller ikke"]],
    legend: [["3{,}40", "3 gjeldende siffer (nullen bakerst teller)", ""], ["0{,}004", "1 gjeldende siffer", ""]],
    ex: "Du regner $2{,}5\\ \\mathrm{m}\\cdot 3{,}142\\ \\mathrm{m}$ og kalkulatoren viser $7{,}855$. Siden $2{,}5$ har færrest siffer (to), oppgis svaret som $7{,}9$ m².",
    tip: "Rund av helt til slutt i utregningen, aldri underveis." },
  en: { t: "Significant figures",
    intro: "Significant figures are the digits in a number that carry real information about how precise the measurement is. Leading zeros do not count, while zeros between other digits and trailing zeros after the decimal point do. An answer can never be more precise than the numbers it was calculated from.",
    f: [["\\text{Multiplying/dividing: fewest digits decide}", "the answer is rounded to as many significant figures as the least precise factor"], ["4.05 \\to 3\\ \\text{digits}", "zeros between digits count"], ["0.0052 \\to 2\\ \\text{digits}", "leading zeros do not count"]],
    legend: [["3.40", "3 significant figures (the trailing zero counts)", ""], ["0.004", "1 significant figure", ""]],
    ex: "You calculate $2.5\\ \\mathrm{m}\\cdot 3.142\\ \\mathrm{m}$ and the calculator shows $7.855$. Since $2.5$ has the fewest digits (two), the answer is given as $7.9$ m².",
    tip: "Round off only at the very end of the calculation, never along the way." } },
{ id: "maleusikkerhet",
  nb: { t: "Måleusikkerhet",
    intro: "Ingen måling er helt eksakt, så den skrives som en verdi pluss/minus en usikkerhet. Den relative usikkerheten forteller hvor stor feilen er sammenlignet med selve verdien, ofte oppgitt i prosent. Når du ganger eller deler størrelser, legger du sammen de relative usikkerhetene deres for å finne usikkerheten i svaret.",
    f: [["x = \\bar x \\pm \\Delta x", "målt verdi med usikkerhet"], ["\\dfrac{\\Delta x}{x}", "relativ usikkerhet"], ["\\dfrac{\\Delta A}{A} \\approx \\dfrac{\\Delta a}{a} + \\dfrac{\\Delta b}{b}", "relative usikkerheter summeres ved $A = ab$"]],
    legend: [["x", "målt verdi", "varierer"], ["\\Delta x", "usikkerhet i målingen", "samme som x"]],
    ex: "En plate måles til $a = 2{,}50 \\pm 0{,}02$ m og $b = 1{,}20 \\pm 0{,}01$ m. Arealet er $A = ab = 3{,}00$ m². Relativ usikkerhet: $0{,}8\\% + 0{,}8\\% \\approx 1{,}6\\%$, så $A = 3{,}00 \\pm 0{,}05$ m².",
    tip: "Legg sammen de relative usikkerhetene ved ganging og deling, ikke de absolutte." },
  en: { t: "Measurement uncertainty",
    intro: "No measurement is completely exact, so it is written as a value plus or minus an uncertainty. The relative uncertainty tells you how large the error is compared with the value itself, often given as a percentage. When you multiply or divide quantities, you add their relative uncertainties to find the uncertainty of the result.",
    f: [["x = \\bar x \\pm \\Delta x", "measured value with uncertainty"], ["\\dfrac{\\Delta x}{x}", "relative uncertainty"], ["\\dfrac{\\Delta A}{A} \\approx \\dfrac{\\Delta a}{a} + \\dfrac{\\Delta b}{b}", "relative uncertainties add for $A = ab$"]],
    legend: [["x", "measured value", "varies"], ["\\Delta x", "uncertainty of the measurement", "same as x"]],
    ex: "A plate is measured as $a = 2.50 \\pm 0.02$ m and $b = 1.20 \\pm 0.01$ m. The area is $A = ab = 3.00$ m². Relative uncertainty: $0.8\\% + 0.8\\% \\approx 1.6\\%$, so $A = 3.00 \\pm 0.05$ m².",
    tip: "Add the relative uncertainties when multiplying and dividing, not the absolute ones." } }
]);

// ================= GFYS – enhet 1: Bevegelse =================
TOPICS("GFYS", 1, [
{ id: "fart-akselerasjon",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 115H220" class="dim"/><circle cx="60" cy="115" r="6" class="af"/><path d="M60 115H140" class="a"/><path d="M140 115l-12-5v10z" class="af"/><text x="30" y="105">s₀</text><text x="95" y="105">v</text><text x="150" y="132">s</text></svg>`,
  nb: { t: "Fart og akselerasjon",
    intro: "Farten forteller hvor mye posisjonen endres per tidsenhet, og akselerasjonen forteller hvor mye farten endres per tidsenhet. Begge kan ha positivt eller negativt fortegn når bevegelsen er langs en rett linje: fortegnet viser retningen i forhold til den du har valgt som positiv.",
    f: [["\\bar v = \\dfrac{\\Delta s}{\\Delta t}", "gjennomsnittsfart"], ["a = \\dfrac{\\Delta v}{\\Delta t}", "akselerasjon"]],
    legend: [["s", "posisjon/strekning", "m"], ["v", "fart", "m/s"], ["a", "akselerasjon", "m/s²"], ["t", "tid", "s"]],
    ex: "En løper flytter seg fra $s = 0$ til $s = 100$ m på $12{,}5$ s. Gjennomsnittsfarten er $\\bar v = 100/12{,}5 = 8{,}0$ m/s.",
    tip: "Samme fortegn på $a$ og $v$ betyr at farten øker; motsatt fortegn betyr nedbremsing." },
  en: { t: "Velocity and acceleration",
    intro: "The velocity tells you how much the position changes per unit time, and the acceleration tells you how much the velocity changes per unit time. Both can be positive or negative for motion along a straight line: the sign shows the direction relative to the one you chose as positive.",
    f: [["\\bar v = \\dfrac{\\Delta s}{\\Delta t}", "average velocity"], ["a = \\dfrac{\\Delta v}{\\Delta t}", "acceleration"]],
    legend: [["s", "position/displacement", "m"], ["v", "velocity", "m/s"], ["a", "acceleration", "m/s²"], ["t", "time", "s"]],
    ex: "A runner moves from $s = 0$ to $s = 100$ m in $12.5$ s. The average velocity is $\\bar v = 100/12.5 = 8.0$ m/s.",
    tip: "The same sign on $a$ and $v$ means the speed is increasing; opposite signs mean it is slowing down." } },
{ id: "bevegelseslikninger",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 120H220" class="dim"/><path d="M20 120V20" class="dim"/><path d="M20 110L100 60L200 30" class="a"/><text x="10" y="20">v</text><text x="210" y="132">t</text></svg>`,
  nb: { t: "Bevegelseslikningene",
    intro: "Når akselerasjonen er konstant, knytter fire likninger sammen startfart, sluttfart, strekning, akselerasjon og tid. Kjenner du tre av de fem størrelsene, kan du finne de to andre ved å velge den likningen som mangler den størrelsen du verken kjenner eller trenger.",
    f: [["v = v_0 + at", "sluttfart etter tiden t"], ["s = v_0t + \\tfrac12 at^2", "strekning"], ["v^2 - v_0^2 = 2as", "uten tid"]],
    legend: [["v_0", "startfart", "m/s"], ["v", "sluttfart", "m/s"], ["a", "akselerasjon", "m/s²"], ["s", "strekning", "m"]],
    ex: "En bil med $v_0 = 20$ m/s bremser med $a = -5{,}0$ m/s² til stillstand. Bremsestrekningen er $s = \\dfrac{v^2-v_0^2}{2a} = \\dfrac{0-400}{-10} = 40$ m.",
    tip: "Velg den likningen som ikke inneholder den størrelsen du verken kjenner eller er ute etter." },
  en: { t: "Equations of motion",
    intro: "When the acceleration is constant, four equations link the initial velocity, final velocity, displacement, acceleration and time. If you know three of the five quantities, you can find the other two by choosing the equation that leaves out the one quantity you neither know nor need.",
    f: [["v = v_0 + at", "final velocity after time t"], ["s = v_0t + \\tfrac12 at^2", "displacement"], ["v^2 - v_0^2 = 2as", "without time"]],
    legend: [["v_0", "initial velocity", "m/s"], ["v", "final velocity", "m/s"], ["a", "acceleration", "m/s²"], ["s", "displacement", "m"]],
    ex: "A car with $v_0 = 20$ m/s brakes at $a = -5.0$ m/s² to a stop. The braking distance is $s = \\dfrac{v^2-v_0^2}{2a} = \\dfrac{0-400}{-10} = 40$ m.",
    tip: "Pick the equation that leaves out the quantity you neither know nor are looking for." } },
{ id: "fritt-fall",
  fig: `<svg viewBox="0 0 240 140"><circle cx="120" cy="30" r="7" class="af"/><path d="M120 40V95" class="a"/><path d="M120 95l-6-13h12z" class="af"/><text x="130" y="70">g</text><path d="M40 118H200" class="dim"/></svg>`,
  nb: { t: "Fritt fall",
    intro: "Uten luftmotstand faller alle legemer med samme akselerasjon, tyngdeakselerasjonen $g$, rett nedover. Det gjelder uansett masse: en stein og en fjær ville falt likt i vakuum. Fritt fall er derfor bare et spesialtilfelle av bevegelseslikningene med $a = g$.",
    f: [["v = v_0 + gt", "fart under fallet"], ["h = v_0t + \\tfrac12 gt^2", "falt høyde"]],
    legend: [["g", "tyngdeakselerasjon", "9{,}81 m/s²"], ["h", "falt høyde", "m"], ["v_0", "startfart (0 ved slipp)", "m/s"]],
    ex: "En stein slippes fra ro. Etter $t = 2{,}0$ s har den falt $h = \\tfrac12\\cdot 9{,}81\\cdot 2{,}0^2 \\approx 19{,}6$ m og har farten $v = 9{,}81\\cdot 2{,}0 \\approx 19{,}6$ m/s.",
    tip: "Velg positiv retning først (ofte nedover), og bruk da $g$ med positivt fortegn i formlene." },
  en: { t: "Free fall",
    intro: "Without air resistance, every body falls with the same acceleration, the gravitational acceleration $g$, straight downward. This holds regardless of mass: a rock and a feather would fall together in a vacuum. Free fall is therefore just a special case of the equations of motion with $a = g$.",
    f: [["v = v_0 + gt", "speed during the fall"], ["h = v_0t + \\tfrac12 gt^2", "distance fallen"]],
    legend: [["g", "gravitational acceleration", "9.81 m/s²"], ["h", "distance fallen", "m"], ["v_0", "initial speed (0 when dropped)", "m/s"]],
    ex: "A rock is dropped from rest. After $t = 2.0$ s it has fallen $h = \\tfrac12\\cdot 9.81\\cdot 2.0^2 \\approx 19.6$ m and has speed $v = 9.81\\cdot 2.0 \\approx 19.6$ m/s.",
    tip: "Choose the positive direction first (often downward), and then use $g$ with a positive sign in the formulas." } },
{ id: "kast",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 110H220" class="dim"/><path d="M30 110Q100 30 190 105" class="a"/><path d="M188 100l6 10 10-6" class="af"/><path d="M30 110l20-14" class="d"/><text x="20" y="100">v₀</text><text x="40" y="90">θ</text></svg>`,
  nb: { t: "Kast (projektilbevegelse)",
    intro: "Kastes noe skrått ut, kan bevegelsen deles i en vannrett del med konstant fart og en loddrett del med fritt fall. De to retningene påvirker ikke hverandre, så du løser dem hver for seg og kobler dem sammen bare gjennom tiden $t$.",
    f: [["x = v_0\\cos\\theta\\cdot t", "vannrett posisjon"], ["y = v_0\\sin\\theta\\cdot t - \\tfrac12 gt^2", "loddrett posisjon (oppover positiv)"]],
    legend: [["v_0", "startfart", "m/s"], ["\\theta", "utskytningsvinkel", "°"], ["x,\\ y", "vannrett/loddrett posisjon", "m"]],
    ex: "En ball kastes med $v_0 = 15$ m/s i $\\theta = 30^\\circ$. Vannrett fartskomponent: $v_0\\cos 30^\\circ \\approx 13$ m/s. Etter $t = 1{,}0$ s: $x \\approx 13$ m.",
    tip: "Del alltid opp i en x- og en y-komponent først – tiden er det eneste som binder dem sammen." },
  en: { t: "Projectile motion",
    intro: "When something is thrown at an angle, the motion splits into a horizontal part with constant velocity and a vertical part with free fall. The two directions do not affect each other, so you solve them separately and connect them only through the time $t$.",
    f: [["x = v_0\\cos\\theta\\cdot t", "horizontal position"], ["y = v_0\\sin\\theta\\cdot t - \\tfrac12 gt^2", "vertical position (upward positive)"]],
    legend: [["v_0", "initial speed", "m/s"], ["\\theta", "launch angle", "°"], ["x,\\ y", "horizontal/vertical position", "m"]],
    ex: "A ball is thrown at $v_0 = 15$ m/s at $\\theta = 30^\\circ$. Horizontal component: $v_0\\cos 30^\\circ \\approx 13$ m/s. After $t = 1.0$ s: $x \\approx 13$ m.",
    tip: "Always split into an x- and a y-component first – time is the only thing that connects them." } }
]);

// ================= GFYS – enhet 2: Krefter og Newtons lover =================
TOPICS("GFYS", 2, [
{ id: "newtons-lover",
  fig: `<svg viewBox="0 0 240 140"><rect x="90" y="70" width="60" height="30" class="fill"/><path d="M90 70h60v30h-60z" class="d"/><path d="M150 85H210" class="a"/><path d="M210 85l-12-5v10z" class="af"/><path d="M120 100V125" class="g"/><path d="M120 125l-6-13h12z" class="gf"/><text x="215" y="80">F</text><text x="126" y="118">G</text></svg>`,
  nb: { t: "Newtons lover",
    intro: "Newtons tre lover binder sammen kraft og bevegelse. Første lov sier at et legeme uten nettokraft holder farten konstant. Andre lov gir sammenhengen mellom kraftsum og akselerasjon. Tredje lov sier at krefter alltid kommer i par som virker på hvert sitt legeme, og derfor aldri opphever hverandre.",
    f: [["\\sum F = ma", "Newtons 2. lov"], ["F_{A\\to B} = -F_{B\\to A}", "Newtons 3. lov"]],
    legend: [["F", "kraft", "N"], ["m", "masse", "kg"], ["a", "akselerasjon", "m/s²"]],
    ex: "En kloss på $m = 5{,}0$ kg påvirkes av en nettokraft på $20$ N. Akselerasjonen blir $a = F/m = 20/5{,}0 = 4{,}0$ m/s².",
    tip: "Kraft og motkraft (3. lov) virker på to forskjellige legemer og kan derfor aldri stå i samme kraftdiagram og oppheve hverandre." },
  en: { t: "Newton's laws",
    intro: "Newton's three laws link force and motion. The first law says a body with no net force keeps a constant velocity. The second law relates the net force to the acceleration. The third law says forces always come in pairs acting on two different bodies, so they never cancel each other.",
    f: [["\\sum F = ma", "Newton's second law"], ["F_{A\\to B} = -F_{B\\to A}", "Newton's third law"]],
    legend: [["F", "force", "N"], ["m", "mass", "kg"], ["a", "acceleration", "m/s²"]],
    ex: "A block with $m = 5.0$ kg is acted on by a net force of $20$ N. The acceleration is $a = F/m = 20/5.0 = 4.0$ m/s².",
    tip: "Action and reaction (3rd law) act on two different bodies, so they can never appear in the same free-body diagram and cancel." } },
{ id: "tyngde-normalkraft",
  fig: `<svg viewBox="0 0 240 140"><rect x="90" y="60" width="60" height="30" class="fill"/><path d="M90 60h60v30h-60z" class="d"/><path d="M20 100H220" class="d"/><path d="M120 90V35" class="g"/><path d="M120 35l-6 13h12z" class="gf"/><path d="M120 90V125" class="a"/><path d="M120 125l-6-13h12z" class="af"/><text x="128" y="45">N</text><text x="128" y="118">G</text></svg>`,
  nb: { t: "Tyngde og normalkraft",
    intro: "Tyngden er kraften jorda trekker et legeme med, alltid rettet loddrett nedover. Normalkraften er kraften underlaget presser tilbake med, vinkelrett på flaten. På et vannrett underlag uten andre loddrette krefter er de to like store, men det gjelder ikke generelt.",
    f: [["G = mg", "tyngde"], ["N = mg", "normalkraft på vannrett underlag (ingen andre loddrette krefter)"]],
    legend: [["G", "tyngde", "N"], ["N", "normalkraft", "N"], ["g", "tyngdeakselerasjon", "9{,}81 m/s²"]],
    ex: "En kasse på $m = 40$ kg står i ro på gulvet. Tyngden er $G = 40\\cdot 9{,}81 \\approx 392$ N, og siden det ikke virker andre loddrette krefter, er $N = 392$ N.",
    tip: "Masse er den samme overalt, men tyngde og normalkraft avhenger av situasjonen – ikke sett $N = mg$ uten å sjekke." },
  en: { t: "Weight and normal force",
    intro: "The weight is the force Earth pulls a body with, always directed straight down. The normal force is the force the surface pushes back with, perpendicular to the surface. On a horizontal surface with no other vertical forces the two are equal in size, but that is not true in general.",
    f: [["G = mg", "weight"], ["N = mg", "normal force on a horizontal surface (no other vertical forces)"]],
    legend: [["G", "weight", "N"], ["N", "normal force", "N"], ["g", "gravitational acceleration", "9.81 m/s²"]],
    ex: "A 40 kg crate rests on the floor. Its weight is $G = 40\\cdot 9.81 \\approx 392$ N, and since no other vertical forces act, $N = 392$ N.",
    tip: "Mass is the same everywhere, but weight and normal force depend on the situation – do not set $N = mg$ without checking." } },
{ id: "friksjon",
  fig: `<svg viewBox="0 0 240 140"><rect x="70" y="60" width="60" height="30" class="fill"/><path d="M70 60h60v30h-60z" class="d"/><path d="M20 100H220" class="d"/><path d="M130 75H190" class="a"/><path d="M190 75l-12-5v10z" class="af"/><path d="M70 75H30" class="r"/><path d="M30 75l12-5v10z" class="rf"/><text x="195" y="70">F</text><text x="12" y="70">R</text></svg>`,
  nb: { t: "Friksjon",
    intro: "Friksjon er en kraft langs kontaktflaten som motvirker at et legeme glir eller begynner å gli. Så lenge legemet ligger i ro, tilpasser friksjonen seg og kan ikke bli større enn $\\mu_sN$. Når det glir, er friksjonen konstant lik $\\mu_kN$, motsatt rettet den glidende bevegelsen.",
    f: [["R \\le \\mu_sN", "statisk friksjon (legemet i ro)"], ["R = \\mu_kN", "kinetisk friksjon (legemet glir)"]],
    legend: [["R", "friksjonskraft", "N"], ["N", "normalkraft", "N"], ["\\mu_s,\\ \\mu_k", "statisk/kinetisk friksjonstall", ""]],
    ex: "En kloss på $m = 10$ kg glir med $\\mu_k = 0{,}25$. Normalkraften er $N = 98{,}1$ N, så friksjonen blir $R = 0{,}25\\cdot 98{,}1 \\approx 24{,}5$ N.",
    tip: "Bruk $\\mu_s$ for å sjekke om noe begynner å gli, og $\\mu_k$ (vanligvis mindre) mens det glir." },
  en: { t: "Friction",
    intro: "Friction is a force along the contact surface that opposes a body sliding or starting to slide. As long as the body is at rest, the friction adjusts itself and can never exceed $\\mu_sN$. Once it slides, the friction is constant at $\\mu_kN$, directed opposite to the sliding motion.",
    f: [["R \\le \\mu_sN", "static friction (body at rest)"], ["R = \\mu_kN", "kinetic friction (body sliding)"]],
    legend: [["R", "friction force", "N"], ["N", "normal force", "N"], ["\\mu_s,\\ \\mu_k", "static/kinetic friction coefficient", ""]],
    ex: "A 10 kg block slides with $\\mu_k = 0.25$. The normal force is $N = 98.1$ N, so the friction is $R = 0.25\\cdot 98.1 \\approx 24.5$ N.",
    tip: "Use $\\mu_s$ to check whether something starts to slide, and $\\mu_k$ (usually smaller) while it is sliding." } },
{ id: "skraplan",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 120L200 120L200 40Z" class="d"/><rect x="90" y="72" width="34" height="20" class="fill" transform="rotate(-24 107 82)"/><path d="M107 82l25 45" class="g" transform="rotate(0)"/><path d="M107 82L90 130" class="g"/><path d="M90 130l-4-14 14 4z" class="gf"/><path d="M107 82L150 100" class="a"/><path d="M150 100l-14-2 6 13z" class="af"/><text x="60" y="115">θ</text><text x="155" y="98">F</text></svg>`,
  nb: { t: "Skråplan",
    intro: "På et skråplan deles tyngden i to komponenter: én langs planet som trekker legemet nedover skråningen, og én vinkelrett på planet som normalkraften balanserer. Jo brattere planet er, desto mer av tyngden virker langs bevegelsen og desto mindre trykker legemet mot underlaget.",
    f: [["N = mg\\cos\\theta", "normalkraft"], ["F_{\\parallel} = mg\\sin\\theta", "tyngdekomponent langs planet"]],
    legend: [["\\theta", "helningsvinkel", "°"], ["N", "normalkraft", "N"], ["F_{\\parallel}", "tyngdekomponent langs planet", "N"]],
    ex: "En kloss på $m = 8{,}0$ kg ligger på et skråplan med $\\theta = 20^\\circ$. $F_\\parallel = 8{,}0\\cdot 9{,}81\\cdot\\sin 20^\\circ \\approx 26{,}9$ N, og $N = 8{,}0\\cdot 9{,}81\\cdot\\cos 20^\\circ \\approx 73{,}8$ N.",
    tip: "Legg akselerasjonsaksen langs planet – da slipper du å dele opp normalkraften og friksjonen i x- og y-komponenter." },
  en: { t: "Inclined plane",
    intro: "On an inclined plane the weight splits into two components: one along the plane pulling the body down the slope, and one perpendicular to the plane balanced by the normal force. The steeper the plane, the more of the weight acts along the motion and the less the body presses on the surface.",
    f: [["N = mg\\cos\\theta", "normal force"], ["F_{\\parallel} = mg\\sin\\theta", "weight component along the plane"]],
    legend: [["\\theta", "incline angle", "°"], ["N", "normal force", "N"], ["F_{\\parallel}", "weight component along the plane", "N"]],
    ex: "An 8.0 kg block sits on an incline with $\\theta = 20^\\circ$. $F_\\parallel = 8.0\\cdot 9.81\\cdot\\sin 20^\\circ \\approx 26.9$ N, and $N = 8.0\\cdot 9.81\\cdot\\cos 20^\\circ \\approx 73.8$ N.",
    tip: "Place the acceleration axis along the plane – then you avoid splitting the normal force and friction into x- and y-components." } }
]);

// ================= GFYS – enhet 3: Arbeid, energi og effekt =================
TOPICS("GFYS", 3, [
{ id: "arbeid",
  fig: `<svg viewBox="0 0 240 140"><rect x="60" y="70" width="40" height="26" class="fill"/><path d="M60 70h40v26h-40z" class="d"/><path d="M100 83H180" class="a"/><path d="M180 83l-12-5v10z" class="af"/><path d="M60 108H200" class="dim"/><text x="130" y="76">F</text><text x="120" y="128">s</text></svg>`,
  nb: { t: "Arbeid",
    intro: "Arbeid er energien en kraft overfører når den virker mens noe flytter seg. Bare komponenten av kraften langs bevegelsen gjør arbeid: en kraft vinkelrett på bevegelsen gjør null arbeid, og en kraft som virker mot bevegelsen, som friksjon, gjør negativt arbeid.",
    f: [["W = Fs\\cos\\theta", "arbeid utført av en kraft"]],
    legend: [["W", "arbeid", "J"], ["F", "kraft", "N"], ["s", "strekning", "m"], ["\\theta", "vinkel mellom kraft og bevegelse", "°"]],
    ex: "Du drar en kjelke med $F = 60$ N i en snor som lager $30^\\circ$ med bakken, en strekning på $15$ m. Arbeidet er $W = 60\\cdot 15\\cdot\\cos 30^\\circ \\approx 779$ J.",
    tip: "Bærer du noe vannrett i konstant høyde, gjør den oppadrettede kraften null arbeid – den står vinkelrett på bevegelsen." },
  en: { t: "Work",
    intro: "Work is the energy a force transfers while it acts as something moves. Only the component of the force along the motion does work: a force perpendicular to the motion does zero work, and a force acting against the motion, like friction, does negative work.",
    f: [["W = Fs\\cos\\theta", "work done by a force"]],
    legend: [["W", "work", "J"], ["F", "force", "N"], ["s", "displacement", "m"], ["\\theta", "angle between force and motion", "°"]],
    ex: "You pull a sled with $F = 60$ N in a rope at $30^\\circ$ to the ground, over $15$ m. The work is $W = 60\\cdot 15\\cdot\\cos 30^\\circ \\approx 779$ J.",
    tip: "If you carry something horizontally at constant height, the upward force does zero work – it is perpendicular to the motion." } },
{ id: "kinetisk-potensiell-energi",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 120H220" class="dim"/><circle cx="60" cy="40" r="8" class="fill"/><path d="M60 48V105" class="dash"/><path d="M60 105l-6-13h12z" class="gf"/><circle cx="190" cy="105" r="8" class="fill"/><path d="M190 90H220" class="a"/><path d="M220 90l-12-5v10z" class="af"/><text x="15" y="80">h</text><text x="195" y="80">v</text></svg>`,
  nb: { t: "Kinetisk og potensiell energi",
    intro: "Kinetisk energi er energien i bevegelse og øker med kvadratet av farten. Potensiell energi er lagret energi på grunn av posisjon, for eksempel høyde i tyngdefeltet. Høyden måles fra et nullnivå du velger selv, og bare forskjeller i høyde har betydning.",
    f: [["E_k = \\tfrac12 mv^2", "kinetisk energi"], ["E_p = mgh", "potensiell energi i tyngdefeltet"]],
    legend: [["E_k", "kinetisk energi", "J"], ["E_p", "potensiell energi", "J"], ["v", "fart", "m/s"], ["h", "høyde over nullnivå", "m"]],
    ex: "En sykkel med rytter, $m = 80$ kg, holder $v = 10$ m/s. Kinetisk energi: $E_k = \\tfrac12\\cdot 80\\cdot 10^2 = 4000$ J $= 4{,}0$ kJ.",
    tip: "Dobler du farten, firedobler du den kinetiske energien – den avhenger av $v^2$, ikke $v$." },
  en: { t: "Kinetic and potential energy",
    intro: "Kinetic energy is the energy of motion and grows with the square of the speed. Potential energy is stored energy due to position, for example height in a gravitational field. The height is measured from a reference level you choose yourself, and only height differences matter.",
    f: [["E_k = \\tfrac12 mv^2", "kinetic energy"], ["E_p = mgh", "potential energy in a gravitational field"]],
    legend: [["E_k", "kinetic energy", "J"], ["E_p", "potential energy", "J"], ["v", "speed", "m/s"], ["h", "height above the reference level", "m"]],
    ex: "A bicycle with rider, $m = 80$ kg, moves at $v = 10$ m/s. Kinetic energy: $E_k = \\tfrac12\\cdot 80\\cdot 10^2 = 4000$ J $= 4.0$ kJ.",
    tip: "Doubling the speed quadruples the kinetic energy – it depends on $v^2$, not $v$." } },
{ id: "energibevaring",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 30L30 110L210 110" class="d"/><path d="M30 30Q30 100 210 110" class="dash"/><circle cx="35" cy="35" r="7" class="fill"/><circle cx="180" cy="107" r="7" class="fill"/><text x="10" y="25">1</text><text x="185" y="128">2</text></svg>`,
  nb: { t: "Energibevaring",
    intro: "Energi kan ikke oppstå eller forsvinne, bare skifte form. Uten friksjon er summen av kinetisk og potensiell energi konstant, så du kan finne en fart fra en høyde eller omvendt uten å kjenne kreftene underveis. Med friksjon går en del av energien over til varme.",
    f: [["E_{k1} + E_{p1} = E_{k2} + E_{p2}", "energibevaring uten friksjon"], ["E_{k1} + E_{p1} = E_{k2} + E_{p2} + W_f", "med friksjonsarbeid $W_f$"]],
    legend: [["E_k", "kinetisk energi", "J"], ["E_p", "potensiell energi", "J"], ["W_f", "friksjonsarbeid", "J"]],
    ex: "En ball slippes fra $h = 5{,}0$ m uten luftmotstand. Energibevaring gir $mgh = \\tfrac12 mv^2$, så $v = \\sqrt{2gh} = \\sqrt{2\\cdot 9{,}81\\cdot 5{,}0} \\approx 9{,}9$ m/s.",
    tip: "Massen forkortes ofte bort i energibevaring – du trenger den sjelden for å finne en fart fra en høyde." },
  en: { t: "Conservation of energy",
    intro: "Energy cannot be created or destroyed, only change form. Without friction, the sum of kinetic and potential energy is constant, so you can find a speed from a height or the other way around without knowing the forces along the way. With friction, part of the energy turns into heat.",
    f: [["E_{k1} + E_{p1} = E_{k2} + E_{p2}", "conservation of energy without friction"], ["E_{k1} + E_{p1} = E_{k2} + E_{p2} + W_f", "with friction work $W_f$"]],
    legend: [["E_k", "kinetic energy", "J"], ["E_p", "potential energy", "J"], ["W_f", "friction work", "J"]],
    ex: "A ball is dropped from $h = 5.0$ m with no air resistance. Energy conservation gives $mgh = \\tfrac12 mv^2$, so $v = \\sqrt{2gh} = \\sqrt{2\\cdot 9.81\\cdot 5.0} \\approx 9.9$ m/s.",
    tip: "The mass often cancels out in energy conservation – you rarely need it to find a speed from a height." } },
{ id: "effekt-virkningsgrad",
  nb: { t: "Effekt og virkningsgrad",
    intro: "Effekt er hvor raskt energi overføres eller arbeid utføres, målt i watt. Virkningsgraden til en maskin er forholdet mellom nyttig effekt ut og tilført effekt inn, og er alltid mindre enn 1 fordi noe alltid blir til varme underveis.",
    f: [["P = \\dfrac{W}{t}", "effekt, arbeid per tid"], ["P = Fv", "effekt ved konstant fart"], ["\\eta = \\dfrac{P_{ut}}{P_{inn}}", "virkningsgrad"]],
    legend: [["P", "effekt", "W"], ["\\eta", "virkningsgrad", ""], ["t", "tid", "s"]],
    ex: "En motor har $\\eta = 0{,}80$ og leverer $2{,}0$ kW nyttig effekt. Tilført effekt er $P_{inn} = P_{ut}/\\eta = 2{,}0/0{,}80 = 2{,}5$ kW.",
    tip: "Tilført effekt er alltid større enn nyttig effekt – del nyttig effekt på $\\eta$, ikke omvendt." },
  en: { t: "Power and efficiency",
    intro: "Power is how quickly energy is transferred or work is done, measured in watts. A machine's efficiency is the ratio of useful power out to input power, and is always less than 1 because some energy always turns into heat along the way.",
    f: [["P = \\dfrac{W}{t}", "power, work per time"], ["P = Fv", "power at constant speed"], ["\\eta = \\dfrac{P_{out}}{P_{in}}", "efficiency"]],
    legend: [["P", "power", "W"], ["\\eta", "efficiency", ""], ["t", "time", "s"]],
    ex: "A motor has $\\eta = 0.80$ and delivers $2.0$ kW of useful power. The input power is $P_{in} = P_{out}/\\eta = 2.0/0.80 = 2.5$ kW.",
    tip: "Input power is always larger than useful power – divide useful power by $\\eta$, not the other way around." } }
]);

// ================= GFYS – enhet 4: Trykk, tetthet og varme =================
TOPICS("GFYS", 4, [
{ id: "tetthet",
  nb: { t: "Tetthet",
    intro: "Tetthet forteller hvor mye masse som er pakket inn i et gitt volum, og er en egenskap ved stoffet, ikke ved gjenstandens størrelse. Vann har tetthet omtrent 1000 kg/m³, altså 1 kg per liter, og er et nyttig sammenligningspunkt for andre stoffer.",
    f: [["\\rho = \\dfrac{m}{V}", "tetthet"]],
    legend: [["\\rho", "tetthet", "kg/m³"], ["m", "masse", "kg"], ["V", "volum", "m³"]],
    ex: "En metallbit har $m = 0{,}89$ kg og $V = 100$ cm³ $= 1{,}0\\cdot 10^{-4}$ m³. Tettheten er $\\rho = 0{,}89/(1{,}0\\cdot 10^{-4}) = 8900$ kg/m³, altså trolig kobber.",
    tip: "Husk å gjøre om cm³ til m³ ($1$ cm³ $= 10^{-6}$ m³) før du regner ut tettheten i kg/m³." },
  en: { t: "Density",
    intro: "Density tells you how much mass is packed into a given volume, and is a property of the substance, not of the object's size. Water has a density of about 1000 kg/m³, that is 1 kg per liter, and is a useful reference point for other substances.",
    f: [["\\rho = \\dfrac{m}{V}", "density"]],
    legend: [["\\rho", "density", "kg/m³"], ["m", "mass", "kg"], ["V", "volume", "m³"]],
    ex: "A metal piece has $m = 0.89$ kg and $V = 100$ cm³ $= 1.0\\cdot 10^{-4}$ m³. The density is $\\rho = 0.89/(1.0\\cdot 10^{-4}) = 8900$ kg/m³, likely copper.",
    tip: "Remember to convert cm³ to m³ ($1$ cm³ $= 10^{-6}$ m³) before computing the density in kg/m³." } },
{ id: "trykk-vaeske",
  fig: `<svg viewBox="0 0 240 140"><rect x="50" y="30" width="140" height="90" class="d"/><path d="M50 30H190" class="dash"/><path d="M110 30V70" class="dim"/><text x="115" y="55">h</text><path d="M60 70H100" class="a"/><path d="M100 70l-12-5v10z" class="af"/><path d="M170 70H210" class="a"/><path d="M210 70l-12-5v10z" class="af"/><path d="M115 118H155" class="a"/><path d="M115 118l12-5v10z M155 118l-12-5v10z" class="af"/></svg>`,
  nb: { t: "Trykk i en væske",
    intro: "Trykket i en væske i ro øker med dybden, fordi hver væskesøyle må bære vekten av alt som ligger over. Overtrykket er trykket fra selve væsken, mens det absolutte trykket også regner med lufttrykket på overflaten. Trykket virker likt i alle retninger i et gitt punkt.",
    f: [["p = p_0 + \\rho gh", "trykk i dybden h (absolutt trykk)"], ["p_{over} = \\rho gh", "overtrykk fra væsken alene"]],
    legend: [["p_0", "trykk på overflaten (ofte $p_{atm}$)", "Pa"], ["\\rho", "tetthet", "kg/m³"], ["h", "dybde", "m"]],
    ex: "En dykker er $h = 10$ m under overflaten. Overtrykket er $\\rho gh = 1000\\cdot 9{,}81\\cdot 10 \\approx 98{,}1$ kPa, så det absolutte trykket er $101{,}3 + 98{,}1 \\approx 199{,}4$ kPa.",
    tip: "Trykket i en væske avhenger bare av dybden, ikke av beholderens form eller totale volum." },
  en: { t: "Pressure in a liquid",
    intro: "The pressure in a liquid at rest increases with depth, because each column of liquid must support the weight of everything above it. The gauge pressure is the pressure from the liquid alone, while the absolute pressure also includes the atmospheric pressure at the surface. Pressure acts equally in all directions at a given point.",
    f: [["p = p_0 + \\rho gh", "pressure at depth h (absolute pressure)"], ["p_{gauge} = \\rho gh", "gauge pressure from the liquid alone"]],
    legend: [["p_0", "pressure at the surface (often $p_{atm}$)", "Pa"], ["\\rho", "density", "kg/m³"], ["h", "depth", "m"]],
    ex: "A diver is $h = 10$ m below the surface. The gauge pressure is $\\rho gh = 1000\\cdot 9.81\\cdot 10 \\approx 98.1$ kPa, so the absolute pressure is $101.3 + 98.1 \\approx 199.4$ kPa.",
    tip: "The pressure in a liquid depends only on the depth, not on the shape or total volume of the container." } },
{ id: "oppdrift",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 60H210" class="dash"/><rect x="90" y="60" width="60" height="45" class="fill"/><path d="M90 60h60v45h-60z" class="d"/><path d="M120 60V25" class="a"/><path d="M120 25l-6 13h12z" class="af"/><path d="M120 105V135" class="g"/><path d="M120 135l-6-13h12z" class="gf"/><text x="128" y="40">F_B</text><text x="128" y="122">G</text></svg>`,
  nb: { t: "Oppdrift",
    intro: "En gjenstand i en væske får en oppdriftskraft oppover som er lik tyngden av væsken den fortrenger, uavhengig av gjenstandens egen tetthet. Er tettheten til gjenstanden mindre enn væskens, flyter den; er den større, synker den.",
    f: [["F_B = \\rho_{vaeske}Vg", "oppdrift, V er volumet under overflaten"]],
    legend: [["F_B", "oppdriftskraft", "N"], ["\\rho_{vaeske}", "tetthet til væsken", "kg/m³"], ["V", "neddykket volum", "m³"]],
    ex: "En stein med $V = 0{,}002$ m³ senkes helt ned i vann ($\\rho = 1000$ kg/m³). Oppdriften er $F_B = 1000\\cdot 0{,}002\\cdot 9{,}81 \\approx 19{,}6$ N.",
    tip: "Bruk alltid tettheten til væsken, ikke til gjenstanden, i oppdriftsformelen." },
  en: { t: "Buoyancy",
    intro: "An object in a fluid feels an upward buoyant force equal to the weight of the fluid it displaces, regardless of the object's own density. If the object's density is lower than the fluid's, it floats; if higher, it sinks.",
    f: [["F_B = \\rho_{fluid}Vg", "buoyant force, V is the submerged volume"]],
    legend: [["F_B", "buoyant force", "N"], ["\\rho_{fluid}", "density of the fluid", "kg/m³"], ["V", "submerged volume", "m³"]],
    ex: "A rock with $V = 0.002$ m³ is fully submerged in water ($\\rho = 1000$ kg/m³). The buoyant force is $F_B = 1000\\cdot 0.002\\cdot 9.81 \\approx 19.6$ N.",
    tip: "Always use the density of the fluid, not of the object, in the buoyancy formula." } },
{ id: "varmekapasitet",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 120H100V50H30z" class="d"/><path d="M45 115V65 M60 115V65 M75 115V65 M90 115V65" class="dim"/><path d="M130 85H180" class="a"/><path d="M180 85l-12-5v10z" class="af"/><text x="140" y="75">Q</text><text x="55" y="40">T</text></svg>`,
  nb: { t: "Varmekapasitet",
    intro: "Varme er energi som overføres på grunn av en temperaturforskjell. Hvor mye varme som trengs for å endre temperaturen til et stoff, avhenger av massen og av den spesifikke varmekapasiteten, som forteller hvor mye energi 1 kg av stoffet trenger for å endre temperaturen 1 grad.",
    f: [["Q = mc\\Delta T", "varme ved temperaturendring uten faseovergang"]],
    legend: [["Q", "varme", "J"], ["c", "spesifikk varmekapasitet", "J/(kg·K)"], ["\\Delta T", "temperaturendring", "K"]],
    ex: "En vannkoker varmer $1{,}5$ kg vann ($c = 4180$ J/(kg·K)) fra $15$ °C til $100$ °C. $Q = 1{,}5\\cdot 4180\\cdot 85 \\approx 533$ kJ.",
    tip: "En endring på $1$ °C er det samme som $1$ K, så $\\Delta T$ trenger ikke regnes om mellom skalaene." },
  en: { t: "Heat capacity",
    intro: "Heat is energy transferred because of a temperature difference. How much heat is needed to change a substance's temperature depends on its mass and on the specific heat capacity, which tells you how much energy 1 kg of the substance needs to change temperature by 1 degree.",
    f: [["Q = mc\\Delta T", "heat for a temperature change with no phase change"]],
    legend: [["Q", "heat", "J"], ["c", "specific heat capacity", "J/(kg·K)"], ["\\Delta T", "temperature change", "K"]],
    ex: "A kettle heats $1.5$ kg of water ($c = 4180$ J/(kg·K)) from $15$ °C to $100$ °C. $Q = 1.5\\cdot 4180\\cdot 85 \\approx 533$ kJ.",
    tip: "A change of $1$ °C is the same as $1$ K, so $\\Delta T$ never needs converting between the scales." } },
{ id: "faseoverganger",
  nb: { t: "Faseoverganger",
    intro: "Når et stoff smelter eller fordamper, holder temperaturen seg konstant mens all tilført varme går med til å bryte bindinger mellom molekylene. Varmen som trengs, kalles smelte- eller fordampingsvarme og er ofte langt større enn varmen som trengs for en vanlig temperaturendring.",
    f: [["Q = mL", "varme ved faseovergang"]],
    legend: [["Q", "varme", "J"], ["L", "smelte- eller fordampingsvarme", "J/kg"], ["m", "masse", "kg"]],
    ex: "For å smelte $0{,}5$ kg is ($L = 334$ kJ/kg) trengs $Q = 0{,}5\\cdot 334 = 167$ kJ – selve smeltingen, uten noen temperaturendring.",
    tip: "Bruk $Q = mc\\Delta T$ for temperaturendring og $Q = mL$ for faseoverganger – aldri begge for samme trinn." },
  en: { t: "Phase changes",
    intro: "When a substance melts or vaporizes, its temperature stays constant while all the heat added goes into breaking bonds between the molecules. The heat needed is called the heat of fusion or vaporization and is often much larger than the heat needed for an ordinary temperature change.",
    f: [["Q = mL", "heat for a phase change"]],
    legend: [["Q", "heat", "J"], ["L", "heat of fusion or vaporization", "J/kg"], ["m", "mass", "kg"]],
    ex: "To melt $0.5$ kg of ice ($L = 334$ kJ/kg) requires $Q = 0.5\\cdot 334 = 167$ kJ – the melting itself, with no temperature change.",
    tip: "Use $Q = mc\\Delta T$ for a temperature change and $Q = mL$ for a phase change – never both for the same step." } }
]);

// ================= GFYS – enhet 5: Elektrisitet =================
TOPICS("GFYS", 5, [
{ id: "ohms-lov",
  fig: `<svg viewBox="0 0 240 140"><path d="M40 70H90" class="d"/><path d="M90 55h50v30h-50z" class="d"/><path d="M140 70H200" class="d"/><path d="M40 70V110H200V70" class="d"/><path d="M55 100H80" class="a"/><path d="M80 100l-10-4v8z" class="af"/><text x="105" y="75">R</text><text x="55" y="95">I</text></svg>`,
  nb: { t: "Ohms lov",
    intro: "Strøm er ladning per tid, spenning er energi per ladning, og resistans er komponentens motstand mot strømmen. Ohms lov binder disse tre sammen: dobler du spenningen over en gitt motstand, dobler du strømmen. Loven gjelder for de fleste vanlige komponenter som ledninger og motstander.",
    f: [["U = RI", "Ohms lov"], ["I = \\dfrac{Q}{t}", "strøm, ladning per tid"]],
    legend: [["U", "spenning", "V"], ["I", "strøm", "A"], ["R", "resistans", "\\Omega"]],
    ex: "Et batteri på $U = 12$ V er koblet til en motstand $R = 8{,}0$ Ω. Strømmen blir $I = U/R = 12/8{,}0 = 1{,}5$ A.",
    tip: "Skriv om mA og kΩ til A og Ω før du regner, eller husk at mA ganger kΩ faktisk gir volt direkte." },
  en: { t: "Ohm's law",
    intro: "Current is charge per time, voltage is energy per charge, and resistance is a component's opposition to the current. Ohm's law links these three: doubling the voltage across a given resistance doubles the current. The law holds for most common components such as wires and resistors.",
    f: [["U = RI", "Ohm's law"], ["I = \\dfrac{Q}{t}", "current, charge per time"]],
    legend: [["U", "voltage", "V"], ["I", "current", "A"], ["R", "resistance", "\\Omega"]],
    ex: "A 12 V battery is connected to a resistance $R = 8.0$ Ω. The current becomes $I = U/R = 12/8.0 = 1.5$ A.",
    tip: "Convert mA and kΩ to A and Ω before calculating, or remember that mA times kΩ actually gives volts directly." } },
{ id: "elektrisk-effekt",
  nb: { t: "Elektrisk effekt",
    intro: "Elektrisk effekt er energien som omdannes i en komponent per sekund, for eksempel til varme i en motstand eller lys i en lyspære. Kombinert med Ohms lov kan effekten skrives på tre likeverdige måter, som er nyttige avhengig av hvilke størrelser du kjenner.",
    f: [["P = UI", "elektrisk effekt"], ["P = RI^2", "effekt uttrykt ved strøm og resistans"], ["P = \\dfrac{U^2}{R}", "effekt uttrykt ved spenning og resistans"]],
    legend: [["P", "effekt", "W"], ["U", "spenning", "V"], ["I", "strøm", "A"]],
    ex: "En varmeovn har $R = 24$ Ω og er koblet til $U = 230$ V. Effekten er $P = U^2/R = 230^2/24 \\approx 2204$ W.",
    tip: "Velg den formen for $P$ som passer størrelsene du kjenner – de gir samme svar." },
  en: { t: "Electric power",
    intro: "Electric power is the energy converted in a component each second, for example into heat in a resistor or light in a bulb. Combined with Ohm's law, the power can be written in three equivalent ways, useful depending on which quantities you know.",
    f: [["P = UI", "electric power"], ["P = RI^2", "power in terms of current and resistance"], ["P = \\dfrac{U^2}{R}", "power in terms of voltage and resistance"]],
    legend: [["P", "power", "W"], ["U", "voltage", "V"], ["I", "current", "A"]],
    ex: "A heater has $R = 24$ Ω and is connected to $U = 230$ V. The power is $P = U^2/R = 230^2/24 \\approx 2204$ W.",
    tip: "Pick the form of $P$ that matches the quantities you know – they all give the same answer." } },
{ id: "seriekobling",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 70H60" class="d"/><rect x="60" y="55" width="40" height="30" class="d"/><path d="M100 70H140" class="d"/><rect x="140" y="55" width="40" height="30" class="d"/><path d="M180 70H220" class="d"/><text x="72" y="75">R₁</text><text x="152" y="75">R₂</text></svg>`,
  nb: { t: "Seriekobling",
    intro: "Når komponenter kobles i serie, går samme strøm gjennom alle sammen, mens spenningen fordeler seg mellom dem. Den totale resistansen blir summen av enkeltresistansene, og øker derfor alltid når du legger til flere motstander i serie.",
    f: [["R_{serie} = R_1 + R_2 + \\dots", "total resistans i serie"], ["U = U_1 + U_2 + \\dots", "spenningen fordeler seg"]],
    legend: [["R_{serie}", "total resistans", "\\Omega"], ["I", "samme strøm gjennom alle", "A"]],
    ex: "To motstander $R_1 = 5{,}0$ Ω og $R_2 = 7{,}0$ Ω står i serie. Total resistans er $R = 5{,}0 + 7{,}0 = 12{,}0$ Ω.",
    tip: "I en seriekobling er strømmen den samme overalt – finn den først, og regn deretter ut hver enkelt spenning med $U_i = R_iI$." },
  en: { t: "Series connection",
    intro: "When components are connected in series, the same current flows through all of them, while the voltage is shared between them. The total resistance is the sum of the individual resistances, so it always increases when you add more resistors in series.",
    f: [["R_{series} = R_1 + R_2 + \\dots", "total resistance in series"], ["U = U_1 + U_2 + \\dots", "the voltage is shared"]],
    legend: [["R_{series}", "total resistance", "\\Omega"], ["I", "same current through all", "A"]],
    ex: "Two resistors $R_1 = 5.0$ Ω and $R_2 = 7.0$ Ω are in series. The total resistance is $R = 5.0 + 7.0 = 12.0$ Ω.",
    tip: "In a series connection the current is the same everywhere – find it first, then compute each voltage with $U_i = R_iI$." } },
{ id: "parallellkobling",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 70H60V40H100V40 M60 70V100H100V100" class="d"/><rect x="100" y="25" width="40" height="30" class="d"/><rect x="100" y="85" width="40" height="30" class="d"/><path d="M140 40H180V70H210 M140 100H180V70" class="d"/><text x="108" y="45">R₁</text><text x="108" y="105">R₂</text></svg>`,
  nb: { t: "Parallellkobling",
    intro: "Når komponenter kobles parallelt, er spenningen den samme over hver av dem, mens strømmen deler seg mellom grenene. Den totale resistansen er alltid mindre enn den minste av enkeltresistansene, fordi strømmen får flere veier å gå.",
    f: [["\\dfrac{1}{R_{par}} = \\dfrac{1}{R_1} + \\dfrac{1}{R_2}", "invers total resistans i parallell"], ["R_{par} = \\dfrac{R_1R_2}{R_1+R_2}", "for nøyaktig to motstander"]],
    legend: [["R_{par}", "total resistans", "\\Omega"], ["U", "samme spenning over alle grener", "V"]],
    ex: "To motstander $R_1 = 6{,}0$ Ω og $R_2 = 12{,}0$ Ω står parallelt. $R_{par} = \\dfrac{6{,}0\\cdot 12{,}0}{6{,}0+12{,}0} = 4{,}0$ Ω.",
    tip: "Ikke glem å ta den inverse til slutt i $1/R = 1/R_1 + 1/R_2$ – svaret er ikke $1/R$, men $R$." },
  en: { t: "Parallel connection",
    intro: "When components are connected in parallel, the voltage is the same across each of them, while the current splits between the branches. The total resistance is always smaller than the smallest individual resistance, because the current gets more paths to take.",
    f: [["\\dfrac{1}{R_{par}} = \\dfrac{1}{R_1} + \\dfrac{1}{R_2}", "inverse total resistance in parallel"], ["R_{par} = \\dfrac{R_1R_2}{R_1+R_2}", "for exactly two resistors"]],
    legend: [["R_{par}", "total resistance", "\\Omega"], ["U", "same voltage across all branches", "V"]],
    ex: "Two resistors $R_1 = 6.0$ Ω and $R_2 = 12.0$ Ω are in parallel. $R_{par} = \\dfrac{6.0\\cdot 12.0}{6.0+12.0} = 4.0$ Ω.",
    tip: "Do not forget to take the inverse at the end of $1/R = 1/R_1 + 1/R_2$ – the answer is not $1/R$, but $R$." } }
]);

// ================= MEK1400 – enhet 0: Svingninger og bølger =================
TOPICS("MEK1400", 0, [
{ id: "harmonisk-svingning",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 75H220" class="dim"/><path d="M20 75Q50 20 80 75T140 75T200 75" class="a"/><path d="M20 75V30M20 30l-4 8h8z" class="dim"/><text x="8" y="55">A</text></svg>`,
  nb: { t: "Harmonisk svingning",
    intro: "En harmonisk oscillator beveger seg fram og tilbake rundt en likevektsstilling med et utslag som følger en cosinusfunksjon. Amplituden er det største utslaget, vinkelfrekvensen forteller hvor fort fasen endres, og perioden er tiden for én hel svingning.",
    f: [["x(t) = A\\cos(\\omega t + \\varphi)", "utslag som funksjon av tiden"], ["\\omega = 2\\pi f = \\dfrac{2\\pi}{T}", "sammenheng mellom vinkelfrekvens, frekvens og periode"]],
    legend: [["A", "amplitude", "m"], ["\\omega", "vinkelfrekvens", "rad/s"], ["f", "frekvens", "Hz"], ["T", "periode", "s"]],
    ex: "En svingning har $f = 4{,}0$ Hz. Vinkelfrekvensen er $\\omega = 2\\pi\\cdot 4{,}0 \\approx 25{,}1$ rad/s, og perioden er $T = 1/4{,}0 = 0{,}25$ s.",
    tip: "Ikke bland $\\omega$ (rad/s) og $f$ (Hz) – de skiller seg med en faktor $2\\pi$." },
  en: { t: "Harmonic oscillation",
    intro: "A harmonic oscillator moves back and forth around an equilibrium position with a displacement that follows a cosine function. The amplitude is the largest displacement, the angular frequency tells you how fast the phase changes, and the period is the time for one full oscillation.",
    f: [["x(t) = A\\cos(\\omega t + \\varphi)", "displacement as a function of time"], ["\\omega = 2\\pi f = \\dfrac{2\\pi}{T}", "relation between angular frequency, frequency and period"]],
    legend: [["A", "amplitude", "m"], ["\\omega", "angular frequency", "rad/s"], ["f", "frequency", "Hz"], ["T", "period", "s"]],
    ex: "An oscillation has $f = 4.0$ Hz. The angular frequency is $\\omega = 2\\pi\\cdot 4.0 \\approx 25.1$ rad/s, and the period is $T = 1/4.0 = 0.25$ s.",
    tip: "Do not mix up $\\omega$ (rad/s) and $f$ (Hz) – they differ by a factor of $2\\pi$." } },
{ id: "masse-fjaer-pendel",
  fig: `<svg viewBox="0 0 240 140"><path d="M60 15V35M60 35q10 5 0 10t0 10t0 10t0 10q0 5 10 5" class="d"/><rect x="40" y="80" width="40" height="24" class="fill"/><path d="M40 80h40v24h-40z" class="d"/><path d="M160 15L175 90" class="d"/><circle cx="180" cy="100" r="10" class="fill"/><path d="M160 15L160 40" class="dash"/><text x="140" y="30">θ</text></svg>`,
  nb: { t: "Masse–fjær og pendel",
    intro: "To vanlige systemer svinger harmonisk: en masse festet til en fjær, og en pendel som svinger med små utslag. Perioden avhenger av masse og fjærstivhet i det ene tilfellet, og bare av lengden og tyngdeakselerasjonen i det andre – ikke av massen.",
    f: [["\\omega = \\sqrt{k/m},\\ \\ T = 2\\pi\\sqrt{m/k}", "masse–fjær-system"], ["T = 2\\pi\\sqrt{L/g}", "matematisk pendel, små utslag"]],
    legend: [["k", "fjærstivhet", "N/m"], ["m", "masse", "kg"], ["L", "pendellengde", "m"]],
    ex: "En kloss på $2{,}0$ kg henger i en fjær med $k = 800$ N/m. $\\omega = \\sqrt{800/2{,}0} = 20$ rad/s, så $T = 2\\pi/20 \\approx 0{,}314$ s.",
    tip: "Perioden til en pendel er uavhengig av massen og (ved små utslag) av amplituden." },
  en: { t: "Mass–spring and pendulum",
    intro: "Two common systems oscillate harmonically: a mass attached to a spring, and a pendulum swinging with small amplitudes. The period depends on the mass and spring stiffness in the first case, and only on the length and gravitational acceleration in the second – not on the mass.",
    f: [["\\omega = \\sqrt{k/m},\\ \\ T = 2\\pi\\sqrt{m/k}", "mass–spring system"], ["T = 2\\pi\\sqrt{L/g}", "simple pendulum, small swings"]],
    legend: [["k", "spring stiffness", "N/m"], ["m", "mass", "kg"], ["L", "pendulum length", "m"]],
    ex: "A 2.0 kg block hangs from a spring with $k = 800$ N/m. $\\omega = \\sqrt{800/2.0} = 20$ rad/s, so $T = 2\\pi/20 \\approx 0.314$ s.",
    tip: "The period of a pendulum is independent of the mass and (for small swings) of the amplitude." } },
{ id: "energi-svingning",
  nb: { t: "Energi i svingninger",
    intro: "I en harmonisk svingning veksler energien mellom kinetisk og potensiell form, mens totalenergien holdes konstant uten friksjon. Farten og akselerasjonen er størst i motsatte punkter av bevegelsen: farten er størst i likevektsstillingen, akselerasjonen størst i ytterstillingene.",
    f: [["v_{maks} = A\\omega", "største fart, i likevektsstillingen"], ["a_{maks} = A\\omega^2", "største akselerasjon, i ytterstillingene"], ["E = \\tfrac12 kA^2 = \\tfrac12 mv_{maks}^2", "total svingeenergi"]],
    legend: [["v_{maks}", "største fart", "m/s"], ["a_{maks}", "største akselerasjon", "m/s²"], ["E", "total svingeenergi", "J"]],
    ex: "En svingning har $A = 0{,}10$ m og $\\omega = 20$ rad/s. Største fart: $v_{maks} = 0{,}10\\cdot 20 = 2{,}0$ m/s, i likevektsstillingen.",
    tip: "I ytterstillingene er farten null og akselerasjonen størst – motsatt av i likevektsstillingen." },
  en: { t: "Energy in oscillations",
    intro: "In a harmonic oscillation the energy alternates between kinetic and potential form, while the total energy stays constant without friction. The speed and the acceleration are greatest at opposite points of the motion: the speed is greatest at the equilibrium position, the acceleration greatest at the turning points.",
    f: [["v_{max} = A\\omega", "maximum speed, at the equilibrium position"], ["a_{max} = A\\omega^2", "maximum acceleration, at the turning points"], ["E = \\tfrac12 kA^2 = \\tfrac12 mv_{max}^2", "total oscillation energy"]],
    legend: [["v_{max}", "maximum speed", "m/s"], ["a_{max}", "maximum acceleration", "m/s²"], ["E", "total oscillation energy", "J"]],
    ex: "An oscillation has $A = 0.10$ m and $\\omega = 20$ rad/s. Maximum speed: $v_{max} = 0.10\\cdot 20 = 2.0$ m/s, at the equilibrium position.",
    tip: "At the turning points the speed is zero and the acceleration is greatest – the opposite of the equilibrium position." } },
{ id: "bolger-strenger",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 70H220" class="dim"/><path d="M20 70Q35 30 50 70T80 70T110 70T140 70T170 70T200 70" class="d"/><path d="M20 100V40M220 100V40" class="dim"/><text x="10" y="115">0</text><text x="205" y="115">L</text></svg>`,
  nb: { t: "Bølger på en streng",
    intro: "En bølge er en svingning som brer seg i rommet. På en streng bestemmes bølgefarten av strekkraften og massen per lengde. Når strengen er fast i begge ender, kan bare bestemte bølgelengder danne stående bølger, og de gir strengens mulige toner.",
    f: [["v = f\\lambda", "sammenheng mellom bølgefart, frekvens og bølgelengde"], ["v = \\sqrt{F/\\mu}", "bølgefart på en streng"], ["f_n = \\dfrac{nv}{2L}", "stående bølger, fast i begge ender, n = 1, 2, 3, ..."]],
    legend: [["\\mu", "masse per lengde", "kg/m"], ["F", "strekkraft", "N"], ["L", "strengens lengde", "m"]],
    ex: "En streng på $L = 0{,}65$ m med $F = 80$ N og $\\mu = 0{,}5$ g/m gir $v = \\sqrt{80/0{,}0005} = 400$ m/s, så grunntonen er $f_1 = 400/(2\\cdot 0{,}65) \\approx 308$ Hz.",
    tip: "Grunntonen har bare én halv bølgelengde mellom endepunktene: $L = \\lambda/2$, ikke $L = \\lambda$." },
  en: { t: "Waves on a string",
    intro: "A wave is an oscillation that travels through space. On a string, the wave speed is set by the tension and the mass per unit length. When the string is fixed at both ends, only certain wavelengths can form standing waves, and these give the string's possible tones.",
    f: [["v = f\\lambda", "relation between wave speed, frequency and wavelength"], ["v = \\sqrt{F/\\mu}", "wave speed on a string"], ["f_n = \\dfrac{nv}{2L}", "standing waves, fixed at both ends, n = 1, 2, 3, ..."]],
    legend: [["\\mu", "mass per unit length", "kg/m"], ["F", "tension", "N"], ["L", "length of the string", "m"]],
    ex: "A string with $L = 0.65$ m, $F = 80$ N and $\\mu = 0.5$ g/m gives $v = \\sqrt{80/0.0005} = 400$ m/s, so the fundamental is $f_1 = 400/(2\\cdot 0.65) \\approx 308$ Hz.",
    tip: "The fundamental has only half a wavelength between the endpoints: $L = \\lambda/2$, not $L = \\lambda$." } }
]);

// ================= MEK1400 – enhet 1: Elektrisitet og magnetisme =================
TOPICS("MEK1400", 1, [
{ id: "coulombs-lov",
  fig: `<svg viewBox="0 0 240 140"><circle cx="60" cy="70" r="12" class="fill"/><circle cx="180" cy="70" r="12" class="fill"/><text x="55" y="75">+</text><text x="175" y="75">+</text><path d="M75 70H110" class="a"/><path d="M110 70l-12-5v10z" class="af"/><path d="M165 70H130" class="a"/><path d="M130 70l12-5v10z" class="af"/><text x="80" y="55">F</text><text x="150" y="55">F</text></svg>`,
  nb: { t: "Coulombs lov",
    intro: "Ladde partikler virker på hverandre med en elektrisk kraft som avtar med kvadratet av avstanden. Like ladninger frastøter hverandre, mens ulike ladninger tiltrekker hverandre. Kreftene på de to ladningene er alltid like store og motsatt rettet, som Newtons tredje lov.",
    f: [["F = k\\dfrac{q_1q_2}{r^2}", "Coulombs lov, $k = 8{,}99\\cdot 10^9$ N·m²/C²"]],
    legend: [["q_1,\\ q_2", "ladninger", "C"], ["r", "avstand mellom ladningene", "m"], ["k", "Coulombs konstant", "N·m²/C²"]],
    ex: "To ladninger $q_1 = q_2 = 2{,}0\\ \\mu$C er $0{,}30$ m fra hverandre. $F = 8{,}99\\cdot 10^9\\cdot\\dfrac{(2{,}0\\cdot 10^{-6})^2}{0{,}30^2} \\approx 0{,}40$ N.",
    tip: "Gjør alltid om µC til C og cm til m før du setter tall inn i Coulombs lov." },
  en: { t: "Coulomb's law",
    intro: "Charged particles exert an electric force on each other that falls off with the square of the distance. Like charges repel each other, while opposite charges attract. The forces on the two charges are always equal in size and opposite in direction, as with Newton's third law.",
    f: [["F = k\\dfrac{q_1q_2}{r^2}", "Coulomb's law, $k = 8.99\\cdot 10^9$ N·m²/C²"]],
    legend: [["q_1,\\ q_2", "charges", "C"], ["r", "distance between the charges", "m"], ["k", "Coulomb's constant", "N·m²/C²"]],
    ex: "Two charges $q_1 = q_2 = 2.0\\ \\mu$C are $0.30$ m apart. $F = 8.99\\cdot 10^9\\cdot\\dfrac{(2.0\\cdot 10^{-6})^2}{0.30^2} \\approx 0.40$ N.",
    tip: "Always convert µC to C and cm to m before substituting numbers into Coulomb's law." } },
{ id: "elektrisk-felt-potensial",
  fig: `<svg viewBox="0 0 240 140"><path d="M40 30V110M80 30V110M120 30V110M160 30V110M200 30V110" class="dim"/><path d="M60 30V60" class="a"/><path d="M60 60l-6-13h12z" class="af"/><path d="M20 20h200v100h-200z" class="d"/><text x="15" y="20">+</text><text x="15" y="128">−</text></svg>`,
  nb: { t: "Elektrisk felt og potensial",
    intro: "En ladning lager et elektrisk felt i rommet rundt seg, og feltet virker med kraft på andre ladninger som befinner seg der. Potensialet (spenningen) er energi per ladning: en ladning som beveger seg gjennom en spenningsforskjell, får eller avgir energien $qU$.",
    f: [["E = F/q", "elektrisk felt, kraft per ladning"], ["E = U/d", "felt mellom parallelle plater"], ["U = W/q", "potensial (spenning), energi per ladning"]],
    legend: [["E", "elektrisk felt", "N/C"], ["U", "spenning", "V"], ["d", "avstand mellom platene", "m"]],
    ex: "To parallelle plater med $U = 400$ V står $d = 0{,}02$ m fra hverandre. Feltet mellom dem er $E = 400/0{,}02 = 20\\,000$ N/C.",
    tip: "Feltet mellom parallelle plater er tilnærmet uniformt og gitt av $E = U/d$, uansett hvor mellom platene du er." },
  en: { t: "Electric field and potential",
    intro: "A charge creates an electric field in the space around it, and the field exerts a force on other charges located there. The potential (voltage) is energy per charge: a charge moving through a potential difference gains or loses the energy $qU$.",
    f: [["E = F/q", "electric field, force per charge"], ["E = U/d", "field between parallel plates"], ["U = W/q", "potential (voltage), energy per charge"]],
    legend: [["E", "electric field", "N/C"], ["U", "voltage", "V"], ["d", "distance between the plates", "m"]],
    ex: "Two parallel plates with $U = 400$ V are $d = 0.02$ m apart. The field between them is $E = 400/0.02 = 20{,}000$ N/C.",
    tip: "The field between parallel plates is approximately uniform and given by $E = U/d$, regardless of where between the plates you are." } },
{ id: "magnetisk-kraft",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 30v90M70 30v90M110 30v90M150 30v90M190 30v90" class="dim"/><path d="M100 100H160" class="a"/><path d="M160 100l-12-5v10z" class="af"/><path d="M130 100V60" class="t"/><path d="M130 60l-6 10 12 0z" class="tf"/><text x="165" y="95">v</text><text x="115" y="55">F</text></svg>`,
  nb: { t: "Magnetisk kraft",
    intro: "En ladning som beveger seg i et magnetfelt, kjenner en kraft som står vinkelrett på både farten og feltet, gitt av høyrehåndsregelen. En strømførende leder i et magnetfelt kjenner en tilsvarende kraft, fordi strømmen består av mange bevegelige ladninger.",
    f: [["F = qvB\\sin\\theta", "kraft på en ladning i et magnetfelt"], ["F = BIL\\sin\\theta", "kraft på en strømførende leder"]],
    legend: [["B", "magnetisk flukstetthet", "T"], ["v", "fart", "m/s"], ["I", "strøm", "A"], ["L", "lederens lengde", "m"]],
    ex: "En leder på $L = 0{,}50$ m fører $I = 5{,}0$ A vinkelrett på et felt $B = 0{,}80$ T. Kraften blir $F = 0{,}80\\cdot 5{,}0\\cdot 0{,}50 = 2{,}0$ N.",
    tip: "Magnetkraften står alltid vinkelrett på farten, så den gjør aldri arbeid – den endrer bare retningen på bevegelsen." },
  en: { t: "Magnetic force",
    intro: "A charge moving in a magnetic field feels a force perpendicular to both its velocity and the field, given by the right-hand rule. A current-carrying conductor in a magnetic field feels a similar force, because the current consists of many moving charges.",
    f: [["F = qvB\\sin\\theta", "force on a charge in a magnetic field"], ["F = BIL\\sin\\theta", "force on a current-carrying conductor"]],
    legend: [["B", "magnetic flux density", "T"], ["v", "speed", "m/s"], ["I", "current", "A"], ["L", "length of the conductor", "m"]],
    ex: "A conductor with $L = 0.50$ m carries $I = 5.0$ A perpendicular to a field $B = 0.80$ T. The force is $F = 0.80\\cdot 5.0\\cdot 0.50 = 2.0$ N.",
    tip: "The magnetic force is always perpendicular to the velocity, so it never does work – it only changes the direction of motion." } },
{ id: "induksjon",
  fig: `<svg viewBox="0 0 240 140"><rect x="70" y="40" width="70" height="55" class="d"/><path d="M70 40l70 55M140 40l-70 55" class="dim"/><path d="M160 55L200 40" class="a"/><path d="M200 40l-13 2 4 11z" class="af"/><text x="95" y="30">Φ</text><text x="165" y="35">B</text></svg>`,
  nb: { t: "Induksjon (Faradays lov)",
    intro: "Magnetisk fluks er et mål på hvor mye magnetfelt som går gjennom en flate. Bare en endring i fluksen induserer en spenning i en spole, og retningen på den induserte strømmen er alltid slik at den motvirker endringen (Lenz' lov).",
    f: [["\\Phi = BA\\cos\\theta", "magnetisk fluks"], ["\\varepsilon = -N\\dfrac{\\Delta\\Phi}{\\Delta t}", "Faradays lov"]],
    legend: [["\\Phi", "magnetisk fluks", "Wb"], ["N", "antall vindinger", ""], ["\\varepsilon", "indusert spenning", "V"]],
    ex: "En spole med $N = 200$ vindinger og $A = 0{,}01$ m² står vinkelrett på et felt som øker med $0{,}5$ T på $0{,}1$ s. $\\varepsilon = 200\\cdot 0{,}01\\cdot 0{,}5/0{,}1 = 10$ V.",
    tip: "Et sterkt, men konstant magnetfelt induserer ingen spenning – bare endring i fluksen teller." },
  en: { t: "Induction (Faraday's law)",
    intro: "Magnetic flux is a measure of how much magnetic field passes through a surface. Only a change in the flux induces a voltage in a coil, and the direction of the induced current is always such that it opposes the change (Lenz's law).",
    f: [["\\Phi = BA\\cos\\theta", "magnetic flux"], ["\\varepsilon = -N\\dfrac{\\Delta\\Phi}{\\Delta t}", "Faraday's law"]],
    legend: [["\\Phi", "magnetic flux", "Wb"], ["N", "number of turns", ""], ["\\varepsilon", "induced voltage", "V"]],
    ex: "A coil with $N = 200$ turns and $A = 0.01$ m² is perpendicular to a field increasing by $0.5$ T over $0.1$ s. $\\varepsilon = 200\\cdot 0.01\\cdot 0.5/0.1 = 10$ V.",
    tip: "A strong but constant magnetic field induces no voltage – only a change in the flux counts." } }
]);

// ================= MEK1400 – enhet 2: Energi og rotasjon =================
TOPICS("MEK1400", 2, [
{ id: "arbeid-energibevaring",
  nb: { t: "Arbeid og energibevaring",
    intro: "Det totale arbeidet på et legeme er lik endringen i dets kinetiske energi. Uten friksjon er summen av kinetisk og potensiell energi konstant gjennom bevegelsen, noe som lar deg finne farter og høyder uten å kjenne kreftene eller tidene underveis.",
    f: [["W_{netto} = \\Delta E_k", "arbeid-energisetningen"], ["E_{k1} + E_{p1} = E_{k2} + E_{p2}", "energibevaring uten friksjon"]],
    legend: [["W", "arbeid", "J"], ["E_k", "kinetisk energi", "J"], ["E_p", "potensiell energi", "J"]],
    ex: "En massiv kloss glir uten friksjon fra $h = 1{,}5$ m høyde. Energibevaring gir $mgh = \\tfrac12 mv^2$, så $v = \\sqrt{2\\cdot 9{,}81\\cdot 1{,}5} \\approx 5{,}42$ m/s.",
    tip: "Sett opp energien før lik energien etter, og legg til friksjonsarbeidet på høyre side hvis det er tap." },
  en: { t: "Work and energy conservation",
    intro: "The total work done on a body equals the change in its kinetic energy. Without friction, the sum of kinetic and potential energy is constant throughout the motion, which lets you find speeds and heights without knowing the forces or times along the way.",
    f: [["W_{net} = \\Delta E_k", "work-energy theorem"], ["E_{k1} + E_{p1} = E_{k2} + E_{p2}", "energy conservation without friction"]],
    legend: [["W", "work", "J"], ["E_k", "kinetic energy", "J"], ["E_p", "potential energy", "J"]],
    ex: "A solid block slides without friction from $h = 1.5$ m. Energy conservation gives $mgh = \\tfrac12 mv^2$, so $v = \\sqrt{2\\cdot 9.81\\cdot 1.5} \\approx 5.42$ m/s.",
    tip: "Set the energy before equal to the energy after, and add the friction work on the right side if there is a loss." } },
{ id: "bevegelsesmengde-stot",
  fig: `<svg viewBox="0 0 240 140"><rect x="30" y="70" width="40" height="30" class="fill"/><rect x="150" y="70" width="40" height="30" class="fill"/><path d="M75 85H110" class="a"/><path d="M110 85l-12-5v10z" class="af"/><path d="M20 118H210" class="dim"/><text x="80" y="78">v₁</text><text x="160" y="65">v₂</text></svg>`,
  nb: { t: "Bevegelsesmengde og støt",
    intro: "Bevegelsesmengden til et legeme er massen ganger farten, og den er bevart i et støt når ytre krefter kan neglisjeres, uansett hvor mye kinetisk energi som går tapt. I et fullstendig uelastisk støt henger legemene sammen etterpå, og en del av den kinetiske energien blir alltid til varme og deformasjon.",
    f: [["p = mv", "bevegelsesmengde"], ["m_1v_1 + m_2v_2 = m_1v_1' + m_2v_2'", "bevaring av bevegelsesmengde i et støt"]],
    legend: [["p", "bevegelsesmengde", "kg·m/s"], ["v,\\ v'", "fart før/etter", "m/s"]],
    ex: "En vogn på $1200$ kg i $15$ m/s treffer en stillestående vogn på $800$ kg, og de henger sammen. $v' = \\dfrac{1200\\cdot 15}{2000} = 9{,}0$ m/s.",
    tip: "Bruk bevegelsesmengde i støt, ikke kinetisk energi – den er bare bevart i fullstendig elastiske støt." },
  en: { t: "Momentum and collisions",
    intro: "The momentum of a body is its mass times its velocity, and it is conserved in a collision when external forces can be neglected, no matter how much kinetic energy is lost. In a perfectly inelastic collision the bodies stick together afterward, and some kinetic energy always turns into heat and deformation.",
    f: [["p = mv", "momentum"], ["m_1v_1 + m_2v_2 = m_1v_1' + m_2v_2'", "conservation of momentum in a collision"]],
    legend: [["p", "momentum", "kg·m/s"], ["v,\\ v'", "speed before/after", "m/s"]],
    ex: "A 1200 kg car at 15 m/s hits a stationary 800 kg car and they stick together. $v' = \\dfrac{1200\\cdot 15}{2000} = 9.0$ m/s.",
    tip: "Use momentum in collisions, not kinetic energy – that is only conserved in perfectly elastic collisions." } },
{ id: "treghetsmoment",
  fig: `<svg viewBox="0 0 240 140"><circle cx="120" cy="75" r="45" class="d"/><circle cx="120" cy="75" r="3" class="af"/><path d="M120 75L165 75" class="a"/><path d="M165 75l-12-5v10z" class="af"/><text x="140" y="70">R</text></svg>`,
  nb: { t: "Rotasjon og treghetsmoment",
    intro: "Treghetsmomentet er rotasjonens motstykke til masse: det forteller hvor vanskelig det er å endre et legemes vinkelfart, og avhenger både av massen og av hvordan den er fordelt i forhold til rotasjonsaksen. Jo lenger unna aksen massen ligger, desto større blir treghetsmomentet.",
    f: [["I = \\sum mr^2", "treghetsmoment, generelt"], ["I = \\tfrac12MR^2", "massiv sylinder om senteraksen"], ["I = \\tfrac25MR^2", "massiv kule om senteraksen"]],
    legend: [["I", "treghetsmoment", "kg·m²"], ["M", "total masse", "kg"], ["R", "radius", "m"]],
    ex: "En massiv sylinder med $M = 4{,}0$ kg og $R = 0{,}20$ m har $I = \\tfrac12\\cdot 4{,}0\\cdot 0{,}20^2 = 0{,}080$ kg·m².",
    tip: "En tynn ring har $I = MR^2$, en massiv sylinder bare $\\tfrac12MR^2$ – massen nær aksen bidrar mindre." },
  en: { t: "Rotation and moment of inertia",
    intro: "The moment of inertia is rotation's counterpart to mass: it tells you how hard it is to change a body's angular velocity, and depends both on the mass and on how it is distributed relative to the rotation axis. The farther the mass lies from the axis, the larger the moment of inertia.",
    f: [["I = \\sum mr^2", "moment of inertia, general"], ["I = \\tfrac12MR^2", "solid cylinder about its central axis"], ["I = \\tfrac25MR^2", "solid sphere about its central axis"]],
    legend: [["I", "moment of inertia", "kg·m²"], ["M", "total mass", "kg"], ["R", "radius", "m"]],
    ex: "A solid cylinder with $M = 4.0$ kg and $R = 0.20$ m has $I = \\tfrac12\\cdot 4.0\\cdot 0.20^2 = 0.080$ kg·m².",
    tip: "A thin hoop has $I = MR^2$, a solid cylinder only $\\tfrac12MR^2$ – mass close to the axis contributes less." } },
{ id: "moment-spinn",
  fig: `<svg viewBox="0 0 240 140"><circle cx="120" cy="75" r="4" class="af"/><path d="M120 75H190" class="b"/><path d="M90 55a34 34 0 0 1 24 -18" class="t"/><path d="M114 37l-11 1 6 8z" class="tf"/><text x="200" y="78">F</text><text x="95" y="35">τ</text></svg>`,
  nb: { t: "Moment og spinn",
    intro: "Newtons andre lov har et rotasjonsmotstykke: kraftmoment gir vinkelakselerasjon, akkurat som kraft gir akselerasjon. Spinnet (dreieimpulsen) er bevart når det ikke virker noe ytre moment på systemet, akkurat som bevegelsesmengden er bevart uten ytre kraft.",
    f: [["\\tau = I\\alpha", "Newtons 2. lov for rotasjon"], ["L = I\\omega", "spinn (dreieimpuls)"], ["E_{rot} = \\tfrac12 I\\omega^2", "rotasjonsenergi"]],
    legend: [["\\tau", "kraftmoment", "Nm"], ["\\alpha", "vinkelakselerasjon", "rad/s²"], ["L", "spinn", "kg·m²/s"]],
    ex: "Et svinghjul med $I = 0{,}50$ kg·m² påvirkes av $\\tau = 2{,}0$ Nm. Vinkelakselerasjonen blir $\\alpha = \\tau/I = 2{,}0/0{,}50 = 4{,}0$ rad/s².",
    tip: "Speedskatere som trekker armene inn, minsker $I$ og øker $\\omega$ – spinnet $L = I\\omega$ holdes bevart." },
  en: { t: "Torque and angular momentum",
    intro: "Newton's second law has a rotational counterpart: torque gives angular acceleration, just as force gives acceleration. Angular momentum is conserved when no external torque acts on the system, just as momentum is conserved without an external force.",
    f: [["\\tau = I\\alpha", "Newton's second law for rotation"], ["L = I\\omega", "angular momentum"], ["E_{rot} = \\tfrac12 I\\omega^2", "rotational kinetic energy"]],
    legend: [["\\tau", "torque", "Nm"], ["\\alpha", "angular acceleration", "rad/s²"], ["L", "angular momentum", "kg·m²/s"]],
    ex: "A flywheel with $I = 0.50$ kg·m² is acted on by $\\tau = 2.0$ Nm. The angular acceleration is $\\alpha = \\tau/I = 2.0/0.50 = 4.0$ rad/s².",
    tip: "A skater pulling their arms in reduces $I$ and increases $\\omega$ – the angular momentum $L = I\\omega$ stays conserved." } },
{ id: "rulling",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 118H220" class="d"/><circle cx="110" cy="88" r="30" class="d"/><path d="M110 88V60" class="dash"/><path d="M110 118Q140 118 160 100" class="a"/><path d="M160 100l-3 12 12-3z" class="af"/><text x="120" y="70">ω</text><text x="150" y="90">v</text></svg>`,
  nb: { t: "Rulling uten gliding",
    intro: "Når noe ruller uten å gli, er den kinetiske energien delt mellom translasjon og rotasjon, og vinkelfarten henger sammen med farten gjennom radiusen. To like tunge legemer med ulik masseform kan derfor få ulik fart nederst i et skråplan, selv om de starter samtidig.",
    f: [["v = \\omega R", "sammenheng mellom fart og vinkelfart ved rulling"], ["E_k = \\tfrac12mv^2 + \\tfrac12I\\omega^2", "total kinetisk energi ved rulling"]],
    legend: [["v", "fart til massesenteret", "m/s"], ["\\omega", "vinkelfart", "rad/s"], ["R", "radius", "m"]],
    ex: "En massiv sylinder ($I = \\tfrac12mR^2$) ruller ned $h = 1{,}5$ m. Energibevaring gir $mgh = \\tfrac34mv^2$, så $v = \\sqrt{4\\cdot 9{,}81\\cdot 1{,}5/3} \\approx 4{,}43$ m/s.",
    tip: "En kloss som glir uten friksjon får høyere fart enn noe som ruller, fordi rulling bruker en del energi på rotasjon." },
  en: { t: "Rolling without slipping",
    intro: "When something rolls without slipping, the kinetic energy is split between translation and rotation, and the angular velocity is linked to the speed through the radius. Two equally heavy bodies with different mass distributions can therefore reach different speeds at the bottom of an incline, even starting together.",
    f: [["v = \\omega R", "relation between speed and angular velocity when rolling"], ["E_k = \\tfrac12mv^2 + \\tfrac12I\\omega^2", "total kinetic energy while rolling"]],
    legend: [["v", "speed of the center of mass", "m/s"], ["\\omega", "angular velocity", "rad/s"], ["R", "radius", "m"]],
    ex: "A solid cylinder ($I = \\tfrac12mR^2$) rolls down $h = 1.5$ m. Energy conservation gives $mgh = \\tfrac34mv^2$, so $v = \\sqrt{4\\cdot 9.81\\cdot 1.5/3} \\approx 4.43$ m/s.",
    tip: "A block sliding without friction reaches a higher speed than something rolling, because rolling spends some energy on rotation." } }
]);

// ================= MATS2100 – enhet 0: Grunnbegreper =================
TOPICS("MATS2100", 0, [
{ id: "idealgassloven",
  fig: `<svg viewBox="0 0 240 140"><rect x="70" y="30" width="90" height="80" class="d"/><path d="M70 60h90" class="dash"/><path d="M100 30v-10M120 30v-10" class="dim"/><text x="105" y="75">p,V</text></svg>`,
  nb: { t: "Idealgassloven",
    intro: "Idealgassloven knytter sammen trykk, volum, temperatur og mengden gass for en ideell gass. Den brukes til å finne én tilstandsstørrelse når de andre er kjent, og gjelder like godt før som etter en prosess, så lenge temperaturen alltid settes inn i kelvin.",
    f: [["pV = nRT", "idealgassloven, $R = 8{,}314$ J/(mol·K)"], ["T[\\mathrm{K}] = t[^\\circ\\mathrm{C}] + 273{,}15", "temperaturomregning"]],
    legend: [["p", "trykk", "Pa"], ["V", "volum", "m³"], ["n", "molmengde", "mol"], ["T", "temperatur", "K"]],
    ex: "$10$ L gass har $p = 200$ kPa og $T = 300$ K. Molmengden er $n = \\dfrac{pV}{RT} = \\dfrac{200\\,000\\cdot 0{,}010}{8{,}314\\cdot 300} \\approx 0{,}802$ mol.",
    tip: "Bruk alltid kelvin i idealgassloven, og gjør trykk og volum om til Pa og m³ når $R = 8{,}314$ J/(mol·K) brukes." },
  en: { t: "Ideal gas law",
    intro: "The ideal gas law links pressure, volume, temperature and the amount of gas for an ideal gas. It is used to find one state property when the others are known, and holds equally well before and after a process, as long as the temperature is always in kelvin.",
    f: [["pV = nRT", "ideal gas law, $R = 8.314$ J/(mol·K)"], ["T[\\mathrm{K}] = t[^\\circ\\mathrm{C}] + 273.15", "temperature conversion"]],
    legend: [["p", "pressure", "Pa"], ["V", "volume", "m³"], ["n", "amount of substance", "mol"], ["T", "temperature", "K"]],
    ex: "10 L of gas has $p = 200$ kPa and $T = 300$ K. The amount is $n = \\dfrac{pV}{RT} = \\dfrac{200{,}000\\cdot 0.010}{8.314\\cdot 300} \\approx 0.802$ mol.",
    tip: "Always use kelvin in the ideal gas law, and convert pressure and volume to Pa and m³ when using $R = 8.314$ J/(mol·K)." } },
{ id: "tilstand-prosesser",
  nb: { t: "Tilstandsstørrelser og prosesser",
    intro: "En tilstandsstørrelse som trykk, volum, temperatur eller indre energi avhenger bare av systemets tilstand akkurat nå, ikke av veien det kom dit. Varme og arbeid er derimot prosesstørrelser som avhenger av selve veien. Prosesser navngis etter hva som holdes konstant underveis.",
    f: [["\\text{Isoterm: } T = \\text{konst.}", "konstant temperatur"], ["\\text{Isobar: } p = \\text{konst.}", "konstant trykk"], ["\\text{Isokor: } V = \\text{konst.}", "konstant volum"]],
    legend: [["U", "indre energi (tilstandsstørrelse)", "J"], ["Q,\\ W", "varme og arbeid (prosesstørrelser)", "J"]],
    ex: "En gass varmes fra $350$ K til $500$ K mens volumet holdes konstant på $0{,}01$ m³ – dette er en isokor prosess, siden bare $V$ er konstant.",
    tip: "$U$ er alltid en tilstandsstørrelse, mens $Q$ og $W$ avhenger av hvilken vei prosessen tok mellom to tilstander." },
  en: { t: "State properties and processes",
    intro: "A state property such as pressure, volume, temperature or internal energy depends only on the system's current state, not on the path it took to get there. Heat and work, on the other hand, are path properties that depend on the process itself. Processes are named after what is held constant along the way.",
    f: [["\\text{Isothermal: } T = \\text{const.}", "constant temperature"], ["\\text{Isobaric: } p = \\text{const.}", "constant pressure"], ["\\text{Isochoric: } V = \\text{const.}", "constant volume"]],
    legend: [["U", "internal energy (state property)", "J"], ["Q,\\ W", "heat and work (path properties)", "J"]],
    ex: "A gas is heated from $350$ K to $500$ K while its volume is held constant at $0.01$ m³ – this is an isochoric process, since only $V$ is constant.",
    tip: "$U$ is always a state property, while $Q$ and $W$ depend on which path the process took between two states." } },
{ id: "forste-hovedsetning",
  fig: `<svg viewBox="0 0 240 140"><rect x="70" y="30" width="90" height="80" class="d"/><path d="M40 55H70" class="a"/><path d="M70 55l-12-5v10z" class="af"/><path d="M160 95H190" class="a"/><path d="M190 95l-12-5v10z" class="af"/><text x="20" y="50">Q</text><text x="195" y="90">W</text><text x="100" y="75">ΔU</text></svg>`,
  nb: { t: "Første hovedsetning",
    intro: "Første hovedsetning er energibevaring anvendt på termodynamiske systemer: tilført varme går enten til å øke systemets indre energi eller til å gjøre arbeid på omgivelsene. Fortegnene må holdes konsekvent, med $W$ som arbeidet systemet selv utfører.",
    f: [["\\Delta U = Q - W", "første hovedsetning, lukket system"]],
    legend: [["\\Delta U", "endring i indre energi", "J"], ["Q", "tilført varme", "J"], ["W", "arbeid utført av systemet", "J"]],
    ex: "Et system mottar $Q = 500$ J varme og gjør $W = 200$ J arbeid på omgivelsene. Endringen i indre energi er $\\Delta U = 500 - 200 = 300$ J.",
    tip: "$W$ er arbeidet systemet gjør på omgivelsene, ikke arbeidet som gjøres på systemet – snu fortegn hvis oppgaven gir det motsatt." },
  en: { t: "The first law",
    intro: "The first law is conservation of energy applied to thermodynamic systems: heat added either increases the system's internal energy or does work on the surroundings. The signs must be kept consistent, with $W$ as the work done by the system itself.",
    f: [["\\Delta U = Q - W", "first law, closed system"]],
    legend: [["\\Delta U", "change in internal energy", "J"], ["Q", "heat added", "J"], ["W", "work done by the system", "J"]],
    ex: "A system receives $Q = 500$ J of heat and does $W = 200$ J of work on the surroundings. The change in internal energy is $\\Delta U = 500 - 200 = 300$ J.",
    tip: "$W$ is the work the system does on the surroundings, not the work done on it – flip the sign if a problem gives the opposite." } },
{ id: "arbeid-konstant-trykk",
  nb: { t: "Arbeid ved konstant trykk",
    intro: "Når en gass utvider seg mot et konstant trykk, for eksempel under et stempel, kan arbeidet skrives enkelt som trykket ganger volumendringen. Kombinert med idealgassloven kan dette arbeidet også uttrykkes direkte ved temperaturendringen, uten å regne ut volumet.",
    f: [["W = p\\,\\Delta V", "arbeid ved konstant trykk"], ["W = nR\\,\\Delta T", "samme arbeid, fra idealgassloven"]],
    legend: [["p", "trykk (konstant)", "Pa"], ["\\Delta V", "volumendring", "m³"], ["\\Delta T", "temperaturendring", "K"]],
    ex: "$2$ mol gass varmes fra $300$ K til $450$ K ved konstant trykk. $W = nR\\,\\Delta T = 2\\cdot 8{,}314\\cdot 150 \\approx 2494$ J $\\approx 2{,}49$ kJ.",
    tip: "$W = nR\\,\\Delta T$ er en snarvei som slipper deg unna å regne ut volumene før og etter separat." },
  en: { t: "Work at constant pressure",
    intro: "When a gas expands against a constant pressure, for example under a piston, the work can be written simply as the pressure times the volume change. Combined with the ideal gas law, this work can also be expressed directly from the temperature change, without computing the volume.",
    f: [["W = p\\,\\Delta V", "work at constant pressure"], ["W = nR\\,\\Delta T", "the same work, from the ideal gas law"]],
    legend: [["p", "pressure (constant)", "Pa"], ["\\Delta V", "volume change", "m³"], ["\\Delta T", "temperature change", "K"]],
    ex: "2 mol of gas is heated from $300$ K to $450$ K at constant pressure. $W = nR\\,\\Delta T = 2\\cdot 8.314\\cdot 150 \\approx 2494$ J $\\approx 2.49$ kJ.",
    tip: "$W = nR\\,\\Delta T$ is a shortcut that avoids computing the volumes before and after separately." } }
]);

// ================= MATS2100 – enhet 1: Varme og entropi =================
TOPICS("MATS2100", 1, [
{ id: "sensibel-latent-varme",
  nb: { t: "Sensibel og latent varme",
    intro: "Sensibel varme endrer temperaturen til et stoff uten å endre fasen, mens latent varme går med til selve faseovergangen mens temperaturen står stille. Ved oppvarming gjennom en faseovergang må du dele opp regningen i separate trinn og legge dem sammen.",
    f: [["Q = mc\\,\\Delta T", "sensibel varme"], ["Q = mL", "latent varme (smelting/fordamping)"]],
    legend: [["c", "spesifikk varmekapasitet", "kJ/(kg·K)"], ["L", "smelte- eller fordampingsvarme", "kJ/kg"]],
    ex: "$0{,}5$ kg is varmes fra $-5$ °C til $0$ °C ($c_{is} = 2{,}1$): $Q_1 = 0{,}5\\cdot 2{,}1\\cdot 5 = 5{,}25$ kJ. Smelting ($L = 334$): $Q_2 = 0{,}5\\cdot 334 = 167$ kJ.",
    tip: "Bruk aldri $Q = mc\\Delta T$ gjennom en faseovergang – der er $\\Delta T = 0$, og du må bruke $Q = mL$." },
  en: { t: "Sensible and latent heat",
    intro: "Sensible heat changes a substance's temperature without changing its phase, while latent heat goes into the phase change itself while the temperature stays constant. When heating through a phase change, split the calculation into separate steps and add them together.",
    f: [["Q = mc\\,\\Delta T", "sensible heat"], ["Q = mL", "latent heat (melting/vaporization)"]],
    legend: [["c", "specific heat capacity", "kJ/(kg·K)"], ["L", "heat of fusion or vaporization", "kJ/kg"]],
    ex: "$0.5$ kg of ice is heated from $-5$ °C to $0$ °C ($c_{ice} = 2.1$): $Q_1 = 0.5\\cdot 2.1\\cdot 5 = 5.25$ kJ. Melting ($L = 334$): $Q_2 = 0.5\\cdot 334 = 167$ kJ.",
    tip: "Never use $Q = mc\\Delta T$ across a phase change – there $\\Delta T = 0$, and you must use $Q = mL$ instead." } },
{ id: "entalpi",
  nb: { t: "Entalpi",
    intro: "Entalpi er en tilstandsstørrelse som kombinerer indre energi med trykk og volum, og er spesielt nyttig for strømningsprosesser ved konstant trykk, som i en turbin eller varmeveksler. Endringen i entalpi svarer da direkte til varmen som tilføres eller fjernes.",
    f: [["H = U + pV", "entalpi"]],
    legend: [["H", "entalpi", "J"], ["U", "indre energi", "J"], ["p", "trykk", "Pa"]],
    ex: "En gass har $U = 500$ J, $p = 100$ kPa og $V = 0{,}002$ m³. Entalpien er $H = 500 + 100\\,000\\cdot 0{,}002 = 700$ J.",
    tip: "Ved konstant trykk er entalpiendringen lik den tilførte varmen: $\\Delta H = Q_p$." },
  en: { t: "Enthalpy",
    intro: "Enthalpy is a state property that combines internal energy with pressure and volume, and is especially useful for flow processes at constant pressure, such as in a turbine or heat exchanger. The change in enthalpy then corresponds directly to the heat added or removed.",
    f: [["H = U + pV", "enthalpy"]],
    legend: [["H", "enthalpy", "J"], ["U", "internal energy", "J"], ["p", "pressure", "Pa"]],
    ex: "A gas has $U = 500$ J, $p = 100$ kPa and $V = 0.002$ m³. The enthalpy is $H = 500 + 100{,}000\\cdot 0.002 = 700$ J.",
    tip: "At constant pressure, the enthalpy change equals the heat added: $\\Delta H = Q_p$." } },
{ id: "entropi-andre-hovedsetning",
  nb: { t: "Entropi og andre hovedsetning",
    intro: "Andre hovedsetning sier at entropien i et isolert system aldri kan avta – den kan bare øke eller holde seg konstant i en ideell, reversibel prosess. Dette forklarer hvorfor varme alltid strømmer fra varmt til kaldt av seg selv, og aldri omvendt.",
    f: [["\\Delta S_{isolert} \\ge 0", "andre hovedsetning"], ["\\Delta S = Q/T", "entropiendring ved konstant temperatur (kelvin)"]],
    legend: [["S", "entropi", "J/K"], ["Q", "varme overført", "J"], ["T", "temperatur", "K"]],
    ex: "$500$ J varme overføres fra et reservoar ved $400$ K. Entropiendringen der er $\\Delta S = -500/400 = -1{,}25$ J/K, og et kaldere reservoar som mottar varmen, får en større positiv økning.",
    tip: "Husk temperaturen i kelvin i $\\Delta S = Q/T$, og at varmen som forlater et system, har negativt fortegn." },
  en: { t: "Entropy and the second law",
    intro: "The second law says the entropy of an isolated system can never decrease – it can only increase or stay constant in an ideal, reversible process. This explains why heat always flows from hot to cold on its own, and never the other way around.",
    f: [["\\Delta S_{isolated} \\ge 0", "the second law"], ["\\Delta S = Q/T", "entropy change at constant temperature (kelvin)"]],
    legend: [["S", "entropy", "J/K"], ["Q", "heat transferred", "J"], ["T", "temperature", "K"]],
    ex: "500 J of heat is transferred from a reservoir at 400 K. The entropy change there is $\\Delta S = -500/400 = -1.25$ J/K, and a colder reservoir receiving the heat gets a larger positive increase.",
    tip: "Remember the temperature in kelvin in $\\Delta S = Q/T$, and that heat leaving a system has a negative sign." } },
{ id: "carnot-virkningsgrad",
  nb: { t: "Carnot-virkningsgrad",
    intro: "Carnot-virkningsgraden er den høyest mulige virkningsgraden en varmekraftmaskin kan ha når den arbeider mellom to gitte temperaturer, og gjelder bare for en ideell, reversibel maskin. Ingen ekte maskin kan overgå den, og den brukes derfor som en fornuftskontroll av beregnede virkningsgrader.",
    f: [["\\eta_{Carnot} = 1 - \\dfrac{T_C}{T_H}", "Carnot-virkningsgrad, temperaturer i kelvin"]],
    legend: [["T_H", "temperatur på det varme reservoaret", "K"], ["T_C", "temperatur på det kalde reservoaret", "K"]],
    ex: "En maskin arbeider mellom $T_H = 600$ K og $T_C = 300$ K. $\\eta_{Carnot} = 1 - 300/600 = 0{,}50$, altså høyst 50 %.",
    tip: "Får du en beregnet virkningsgrad over Carnot-grensen, er noe galt i utregningen – ingen ekte maskin kommer over den." },
  en: { t: "Carnot efficiency",
    intro: "The Carnot efficiency is the highest possible efficiency a heat engine can have while operating between two given temperatures, and applies only to an ideal, reversible engine. No real engine can exceed it, so it serves as a sanity check on a calculated efficiency.",
    f: [["\\eta_{Carnot} = 1 - \\dfrac{T_C}{T_H}", "Carnot efficiency, temperatures in kelvin"]],
    legend: [["T_H", "temperature of the hot reservoir", "K"], ["T_C", "temperature of the cold reservoir", "K"]],
    ex: "An engine operates between $T_H = 600$ K and $T_C = 300$ K. $\\eta_{Carnot} = 1 - 300/600 = 0.50$, so at most 50%.",
    tip: "If a calculated efficiency exceeds the Carnot limit, something is wrong – no real engine can exceed it." } }
]);

// ================= MATS2100 – enhet 2: Kretsprosesser =================
TOPICS("MATS2100", 2, [
{ id: "varmekraftmaskin",
  fig: `<svg viewBox="0 0 240 140"><circle cx="120" cy="75" r="35" class="d"/><path d="M60 40H90" class="a"/><path d="M90 40l-12-5v10z" class="af"/><path d="M150 105H180" class="a"/><path d="M180 105l-12-5v10z" class="af"/><path d="M155 55H190" class="a"/><path d="M190 55l-12-5v10z" class="af"/><text x="30" y="45">Q_H</text><text x="185" y="100">Q_C</text><text x="195" y="50">W</text></svg>`,
  nb: { t: "Varmekraftmaskin",
    intro: "En varmekraftmaskin tar opp varme fra et varmt reservoar, avgir noe til et kaldt reservoar, og leverer resten som nyttig arbeid. Virkningsgraden forteller hvor stor andel av den tilførte varmen som blir til arbeid, og er alltid mindre enn 1.",
    f: [["W = Q_H - Q_C", "energibalanse for en varmekraftmaskin"], ["\\eta = \\dfrac{W}{Q_H} = 1 - \\dfrac{Q_C}{Q_H}", "virkningsgrad"]],
    legend: [["Q_H", "varme fra det varme reservoaret", "J"], ["Q_C", "varme til det kalde reservoaret", "J"], ["W", "levert arbeid", "J"]],
    ex: "En maskin tar opp $Q_H = 800$ kJ og avgir $Q_C = 500$ kJ. Arbeidet er $W = 800 - 500 = 300$ kJ, og virkningsgraden er $\\eta = 300/800 = 0{,}375$.",
    tip: "$Q_H = Q_C + W$ må alltid stemme (energibevaring), uansett hvilken kretsprosess det gjelder." },
  en: { t: "Heat engine",
    intro: "A heat engine takes in heat from a hot reservoir, rejects some to a cold reservoir, and delivers the rest as useful work. The efficiency tells you what fraction of the heat supplied is converted to work, and is always less than 1.",
    f: [["W = Q_H - Q_C", "energy balance for a heat engine"], ["\\eta = \\dfrac{W}{Q_H} = 1 - \\dfrac{Q_C}{Q_H}", "efficiency"]],
    legend: [["Q_H", "heat from the hot reservoir", "J"], ["Q_C", "heat rejected to the cold reservoir", "J"], ["W", "work delivered", "J"]],
    ex: "An engine takes in $Q_H = 800$ kJ and rejects $Q_C = 500$ kJ. The work is $W = 800 - 500 = 300$ kJ, and the efficiency is $\\eta = 300/800 = 0.375$.",
    tip: "$Q_H = Q_C + W$ must always hold (energy conservation), regardless of which cycle is involved." } },
{ id: "varmepumpe-kop",
  nb: { t: "Varmepumpe og COP",
    intro: "En varmepumpe eller et kjøleanlegg bruker arbeid til å flytte varme fra kaldt til varmt, motsatt av naturens egen retning. Ytelsen måles med COP i stedet for virkningsgrad, og COP kan være større enn 1 fordi maskinen flytter varme i stedet for å skape den.",
    f: [["COP_{varme} = \\dfrac{Q_H}{W}", "COP for oppvarming"], ["COP_{varme} = COP_{kulde} + 1", "sammenheng mellom de to COP-ene"]],
    legend: [["COP_{varme}", "ytelsestall for oppvarming", ""], ["COP_{kulde}", "ytelsestall for kjøling", ""]],
    ex: "En varmepumpe med $COP_{varme} = 3{,}2$ skal levere $8$ kW varme. Eleffekten som trengs er $W = Q_H/COP_{varme} = 8/3{,}2 = 2{,}5$ kW.",
    tip: "$COP > 1$ betyr ikke at energi skapes – maskinen flytter bare varme og bruker arbeid til å gjøre det." },
  en: { t: "Heat pump and COP",
    intro: "A heat pump or refrigerator uses work to move heat from cold to hot, the opposite of nature's own direction. Performance is measured with COP instead of efficiency, and COP can be greater than 1 because the machine moves heat rather than creating it.",
    f: [["COP_{heat} = \\dfrac{Q_H}{W}", "COP for heating"], ["COP_{heat} = COP_{cold} + 1", "relation between the two COPs"]],
    legend: [["COP_{heat}", "performance factor for heating", ""], ["COP_{cold}", "performance factor for cooling", ""]],
    ex: "A heat pump with $COP_{heat} = 3.2$ must deliver $8$ kW of heat. The electric power needed is $W = Q_H/COP_{heat} = 8/3.2 = 2.5$ kW.",
    tip: "$COP > 1$ does not mean energy is created – the machine only moves heat and uses work to do so." } },
{ id: "idealiserte-kretsprosesser",
  nb: { t: "Idealiserte kretsprosesser",
    intro: "Idealiserte kretsprosesser er forenklede modeller av virkelige motorer og kraftverk, der hvert trinn er en ren prosess (isoterm, isobar, isokor eller adiabatisk). Modellene skiller seg i hvordan og når varme tilføres, og lar deg regne ut virkningsgrad uten å kjenne alle detaljene i en ekte maskin.",
    f: [["\\text{Otto: varme ved konstant } V", "bensinmotor, momentan tenning"], ["\\text{Diesel: varme ved konstant } p", "dieselmotor"], ["\\text{Brayton: kompresjon–varme–ekspansjon}", "gassturbin/jetmotor, varme ved konstant p"]],
    legend: [["V", "volum", "m³"], ["p", "trykk", "Pa"]],
    ex: "I Otto-prosessen antennes drivstoffet momentant, så varmen tilføres mens stempelet ikke rekker å bevege seg – altså ved tilnærmet konstant volum.",
    tip: "Det som skiller syklusene, er hvordan varmen tilføres: konstant volum (Otto), konstant trykk (Diesel/Brayton) eller konstant entropi ved kompresjon og ekspansjon i begge." },
  en: { t: "Idealized thermodynamic cycles",
    intro: "Idealized cycles are simplified models of real engines and power plants, where each step is a pure process (isothermal, isobaric, isochoric or adiabatic). The models differ in how and when heat is added, and let you calculate efficiency without knowing every detail of a real machine.",
    f: [["\\text{Otto: heat at constant } V", "gasoline engine, instantaneous ignition"], ["\\text{Diesel: heat at constant } p", "diesel engine"], ["\\text{Brayton: compression–heat–expansion}", "gas turbine/jet engine, heat at constant p"]],
    legend: [["V", "volume", "m³"], ["p", "pressure", "Pa"]],
    ex: "In the Otto cycle the fuel ignites instantaneously, so heat is added before the piston has time to move much – approximately at constant volume.",
    tip: "What distinguishes the cycles is how heat is added: constant volume (Otto), constant pressure (Diesel/Brayton), or isentropic compression and expansion in both." } },
{ id: "struping-isentrop",
  nb: { t: "Struping og isentrop prosess",
    intro: "Struping er en irreversibel prosess der en gass eller væske presses gjennom en trang åpning, som en ventil, uten at det gjøres arbeid eller utveksles varme. Entalpien holdes da tilnærmet konstant, men trykket og gjerne temperaturen faller. En isentrop prosess er derimot reversibel og adiabatisk, og brukes til å idealisere turbiner og kompressorer.",
    f: [["h_1 \\approx h_2", "struping, tilnærmet konstant entalpi"], ["Q = 0,\\ \\Delta S = 0", "isentrop prosess"]],
    legend: [["h", "spesifikk entalpi", "kJ/kg"], ["S", "entropi", "J/K"]],
    ex: "Kjølemiddel strupes gjennom en ekspansjonsventil. Entalpien før og etter er tilnærmet lik, men trykket faller kraftig, og en del av væsken fordamper og kjøler resten.",
    tip: "En isentrop prosess er en idealisering uten tap – ekte turbiner og kompressorer kommer nær den, men aldri helt dit." },
  en: { t: "Throttling and isentropic processes",
    intro: "Throttling is an irreversible process where a gas or liquid is forced through a narrow opening, such as a valve, with no work done and no heat exchanged. The enthalpy stays approximately constant, but the pressure and usually the temperature drop. An isentropic process, by contrast, is reversible and adiabatic, and is used to idealize turbines and compressors.",
    f: [["h_1 \\approx h_2", "throttling, approximately constant enthalpy"], ["Q = 0,\\ \\Delta S = 0", "isentropic process"]],
    legend: [["h", "specific enthalpy", "kJ/kg"], ["S", "entropy", "J/K"]],
    ex: "Refrigerant is throttled through an expansion valve. The enthalpy before and after is roughly equal, but the pressure drops sharply, and part of the liquid flashes to vapor and cools the rest.",
    tip: "An isentropic process is a loss-free idealization – real turbines and compressors come close to it, but never exactly reach it." } }
]);

// ================= FLUID – enhet 0: Hydrostatikk =================
TOPICS("FLUID", 0, [
{ id: "hydrostatisk-trykk",
  fig: `<svg viewBox="0 0 240 140"><rect x="50" y="30" width="140" height="90" class="d"/><path d="M50 30H190" class="dash"/><path d="M115 30V80" class="dim"/><text x="120" y="55">h</text><path d="M60 80H100" class="a"/><path d="M100 80l-12-5v10z" class="af"/><path d="M170 80H210" class="a"/><path d="M210 80l-12-5v10z" class="af"/></svg>`,
  nb: { t: "Hydrostatisk trykk",
    intro: "Trykket i en væske i ro øker med dybden, fordi hver væskesøyle må bære vekten av alt vannet over seg. Overtrykket avhenger bare av tetthet, tyngdeakselerasjon og dybde, ikke av beholderens form eller totale volum – dette kalles det hydrostatiske paradokset.",
    f: [["p = p_0 + \\rho gh", "hydrostatisk trykk, absolutt"], ["p_{abs} = p_{atm} + p_{over}", "absolutt trykk fra overtrykk"]],
    legend: [["\\rho", "tetthet", "kg/m³"], ["h", "dybde", "m"], ["p_{atm}", "atmosfæretrykk", "\\approx 101{,}3 kPa"]],
    ex: "En demning har vann $h = 12$ m dypt. Overtrykket ved bunnen er $\\rho gh = 1000\\cdot 9{,}81\\cdot 12 \\approx 117{,}7$ kPa.",
    tip: "Trykket avhenger bare av dybden – en smal og en bred tank med samme dybde har samme trykk ved bunnen." },
  en: { t: "Hydrostatic pressure",
    intro: "The pressure in a fluid at rest increases with depth, because every column of fluid must support the weight of everything above it. The gauge pressure depends only on density, gravitational acceleration and depth, not on the container's shape or total volume – this is the hydrostatic paradox.",
    f: [["p = p_0 + \\rho gh", "hydrostatic pressure, absolute"], ["p_{abs} = p_{atm} + p_{gauge}", "absolute pressure from gauge pressure"]],
    legend: [["\\rho", "density", "kg/m³"], ["h", "depth", "m"], ["p_{atm}", "atmospheric pressure", "\\approx 101.3 kPa"]],
    ex: "A dam holds water $h = 12$ m deep. The gauge pressure at the bottom is $\\rho gh = 1000\\cdot 9.81\\cdot 12 \\approx 117.7$ kPa.",
    tip: "The pressure depends only on the depth – a narrow and a wide tank with the same depth have the same pressure at the bottom." } },
{ id: "arkimedes-oppdrift",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 55H210" class="dash"/><rect x="95" y="55" width="50" height="50" class="fill"/><path d="M95 55h50v50h-50z" class="d"/><path d="M120 55V25" class="a"/><path d="M120 25l-6 13h12z" class="af"/><path d="M120 105V130" class="g"/><path d="M120 130l-6-13h12z" class="gf"/><text x="128" y="35">F_B</text><text x="128" y="122">G</text></svg>`,
  nb: { t: "Arkimedes' prinsipp",
    intro: "Arkimedes' prinsipp sier at oppdriften på et neddykket legeme er lik tyngden av væsken det fortrenger, uansett hvilket materiale legemet består av. Et flytende legeme senker seg akkurat til det fortrenger sin egen vekt i væske.",
    f: [["F_B = \\rho_{v\\text{æ}ske}gV_{fortrengt}", "oppdrift"], ["\\dfrac{V_{under}}{V} = \\dfrac{\\rho_{legeme}}{\\rho_{v\\text{æ}ske}}", "nedsenket volumandel ved flyting"]],
    legend: [["F_B", "oppdriftskraft", "N"], ["V_{fortrengt}", "fortrengt volum", "m³"]],
    ex: "Et isfjell ($\\rho_{is} = 917$ kg/m³) flyter i sjøvann ($\\rho = 1025$ kg/m³). Andelen under vann er $917/1025 \\approx 0{,}895$, så bare ca. 10,5 % stikker opp.",
    tip: "Bruk alltid væskens tetthet i $F_B = \\rho gV$, ikke tettheten til legemet selv." },
  en: { t: "Archimedes' principle",
    intro: "Archimedes' principle states that the buoyant force on a submerged body equals the weight of the fluid it displaces, regardless of what the body is made of. A floating body sinks exactly until it displaces its own weight in fluid.",
    f: [["F_B = \\rho_{fluid}gV_{displaced}", "buoyant force"], ["\\dfrac{V_{under}}{V} = \\dfrac{\\rho_{body}}{\\rho_{fluid}}", "submerged volume fraction while floating"]],
    legend: [["F_B", "buoyant force", "N"], ["V_{displaced}", "displaced volume", "m³"]],
    ex: "An iceberg ($\\rho_{ice} = 917$ kg/m³) floats in seawater ($\\rho = 1025$ kg/m³). The fraction below water is $917/1025 \\approx 0.895$, so only about 10.5% sticks up.",
    tip: "Always use the fluid's density in $F_B = \\rho gV$, not the density of the body itself." } },
{ id: "hydraulisk-presse",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 110H210" class="d"/><rect x="40" y="80" width="30" height="30" class="d"/><rect x="150" y="50" width="60" height="60" class="d"/><path d="M55 70V50" class="a"/><path d="M55 50l-6 13h12z" class="af"/><path d="M180 40V15" class="a"/><path d="M180 15l-6 13h12z" class="af"/><text x="35" y="45">F₁</text><text x="185" y="25">F₂</text><text x="50" y="100">A₁</text><text x="170" y="85">A₂</text></svg>`,
  nb: { t: "Hydraulisk presse",
    intro: "Pascals prinsipp sier at trykket i en lukket, sammenhengende væske er likt overalt. I en hydraulisk presse gir dette en kraftforsterkning: en liten kraft på et lite stempel skaper samme trykk som en mye større kraft på et stort stempel, fordi trykket er kraft delt på areal.",
    f: [["p = \\dfrac{F_1}{A_1} = \\dfrac{F_2}{A_2}", "likt trykk på begge stempler"], ["F_2 = F_1\\dfrac{A_2}{A_1}", "kraftforsterkning"]],
    legend: [["F_1,\\ F_2", "krefter på de to stemplene", "N"], ["A_1,\\ A_2", "arealer av stemplene", "m²"]],
    ex: "En hydraulisk jekk har $A_1 = 5$ cm² og $A_2 = 150$ cm². En kraft $F_1 = 100$ N gir $F_2 = 100\\cdot 150/5 = 3000$ N.",
    tip: "Kraftforsterkningen koster deg forflytning – det lille stempelet må beveges langt mer enn det store." },
  en: { t: "Hydraulic press",
    intro: "Pascal's principle says the pressure in a closed, connected fluid is equal everywhere. In a hydraulic press this gives a force amplification: a small force on a small piston creates the same pressure as a much larger force on a large piston, because pressure is force divided by area.",
    f: [["p = \\dfrac{F_1}{A_1} = \\dfrac{F_2}{A_2}", "equal pressure on both pistons"], ["F_2 = F_1\\dfrac{A_2}{A_1}", "force amplification"]],
    legend: [["F_1,\\ F_2", "forces on the two pistons", "N"], ["A_1,\\ A_2", "areas of the pistons", "m²"]],
    ex: "A hydraulic jack has $A_1 = 5$ cm² and $A_2 = 150$ cm². A force $F_1 = 100$ N gives $F_2 = 100\\cdot 150/5 = 3000$ N.",
    tip: "The force amplification costs you displacement – the small piston must move much farther than the large one." } },
{ id: "manometer",
  fig: `<svg viewBox="0 0 240 140"><path d="M90 20V100Q90 115 105 115H135Q150 115 150 100V50" class="d"/><path d="M90 60H70" class="dim"/><path d="M150 80H170" class="dim"/><path d="M70 60V90" class="a"/><path d="M70 90l-6-13h12z" class="af"/><text x="45" y="80">Δh</text></svg>`,
  nb: { t: "U-rørmanometer",
    intro: "Et U-rørmanometer måler en trykkforskjell ved å la den skape en høydeforskjell i en væskesøyle, ofte kvikksølv fordi det er svært tett og gir en kompakt oppstilling. Trykkforskjellen er direkte proporsjonal med høydeforskjellen.",
    f: [["\\Delta p = \\rho g\\,\\Delta h", "trykkforskjell fra høydeforskjell i manometeret"]],
    legend: [["\\Delta h", "høydeforskjell mellom grenene", "m"], ["\\rho", "tetthet til manometervæsken", "kg/m³"]],
    ex: "Et kvikksølvmanometer ($\\rho = 13\\,600$ kg/m³) viser $\\Delta h = 15$ cm. $\\Delta p = 13\\,600\\cdot 9{,}81\\cdot 0{,}15 \\approx 20{,}0$ kPa.",
    tip: "Kvikksølv brukes fordi den store tettheten gir en kort, lesbar søyle selv ved store trykkforskjeller." },
  en: { t: "U-tube manometer",
    intro: "A U-tube manometer measures a pressure difference by letting it create a height difference in a fluid column, often mercury because it is very dense and gives a compact setup. The pressure difference is directly proportional to the height difference.",
    f: [["\\Delta p = \\rho g\\,\\Delta h", "pressure difference from a height difference in the manometer"]],
    legend: [["\\Delta h", "height difference between the legs", "m"], ["\\rho", "density of the manometer fluid", "kg/m³"]],
    ex: "A mercury manometer ($\\rho = 13{,}600$ kg/m³) shows $\\Delta h = 15$ cm. $\\Delta p = 13{,}600\\cdot 9.81\\cdot 0.15 \\approx 20.0$ kPa.",
    tip: "Mercury is used because its high density gives a short, readable column even at large pressure differences." } }
]);

// ================= FLUID – enhet 1: Kontinuitet og Bernoulli =================
TOPICS("FLUID", 1, [
{ id: "kontinuitet",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 50H100L150 70L100 90H20Z" class="d"/><path d="M150 60H220V80H150Z" class="d"/><path d="M50 75H80" class="a"/><path d="M80 75l-10-4v8z" class="af"/><path d="M175 70H200" class="a"/><path d="M200 70l-10-4v8z" class="af"/><text x="55" y="65">v₁</text><text x="175" y="60">v₂</text></svg>`,
  nb: { t: "Kontinuitet",
    intro: "Kontinuitetsligningen sier at like mye volum (eller masse) må passere hvert tverrsnitt av et rør per sekund, siden væsken verken kan skapes eller forsvinne underveis. Der røret er trangt, må farten derfor øke, og der det er vidt, avtar farten tilsvarende.",
    f: [["Q = Av", "volumstrøm"], ["A_1v_1 = A_2v_2", "kontinuitet langs et rør"]],
    legend: [["Q", "volumstrøm", "m³/s"], ["A", "tverrsnittsareal", "m²"], ["v", "fart", "m/s"]],
    ex: "Et rør snevres fra $d_1 = 100$ mm til $d_2 = 60$ mm med $v_1 = 2$ m/s. $v_2 = v_1(d_1/d_2)^2 = 2\\cdot(100/60)^2 \\approx 5{,}56$ m/s.",
    tip: "Bruk areal, ikke diameter, i kontinuitetsligningen: $A = \\pi d^2/4$." },
  en: { t: "Continuity",
    intro: "The continuity equation says the same volume (or mass) must pass every cross-section of a pipe each second, since the fluid can neither be created nor destroyed along the way. Where the pipe narrows, the speed must therefore increase, and where it widens, the speed decreases accordingly.",
    f: [["Q = Av", "volumetric flow rate"], ["A_1v_1 = A_2v_2", "continuity along a pipe"]],
    legend: [["Q", "volumetric flow rate", "m³/s"], ["A", "cross-sectional area", "m²"], ["v", "speed", "m/s"]],
    ex: "A pipe narrows from $d_1 = 100$ mm to $d_2 = 60$ mm with $v_1 = 2$ m/s. $v_2 = v_1(d_1/d_2)^2 = 2\\cdot(100/60)^2 \\approx 5.56$ m/s.",
    tip: "Use area, not diameter, in the continuity equation: $A = \\pi d^2/4$." } },
{ id: "bernoulli",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 100Q90 40 220 60" class="d"/><circle cx="40" cy="93" r="4" class="af"/><circle cx="190" cy="63" r="4" class="af"/><path d="M40 93V70" class="dim"/><path d="M190 63V40" class="dim"/><text x="20" y="65">z₁</text><text x="195" y="35">z₂</text></svg>`,
  nb: { t: "Bernoullis ligning",
    intro: "Bernoullis ligning er en energibalanse langs en strømlinje for stasjonær, friksjonsfri strømning: summen av trykkenergi, kinetisk energi og potensiell energi er konstant. Der farten øker, må trykket synke, og omvendt, gitt samme høyde.",
    f: [["p + \\tfrac12\\rho v^2 + \\rho gz = \\text{konstant}", "Bernoullis ligning langs en strømlinje"]],
    legend: [["p", "statisk trykk", "Pa"], ["v", "fart", "m/s"], ["z", "høyde", "m"]],
    ex: "Vann strømmer horisontalt: $v_1 = 2$ m/s ved $p_1$, og $v_2 = 5{,}56$ m/s der røret er trangt. $p_1 - p_2 = \\tfrac12\\cdot 1000\\cdot(5{,}56^2 - 2^2) \\approx 13{,}4$ kPa.",
    tip: "Bernoulli gjelder bare uten tap og uten pumpe mellom punktene – legg til slike ledd separat hvis de finnes." },
  en: { t: "Bernoulli's equation",
    intro: "Bernoulli's equation is an energy balance along a streamline for steady, frictionless flow: the sum of pressure energy, kinetic energy and potential energy is constant. Where the speed increases, the pressure must drop, and vice versa, at the same height.",
    f: [["p + \\tfrac12\\rho v^2 + \\rho gz = \\text{constant}", "Bernoulli's equation along a streamline"]],
    legend: [["p", "static pressure", "Pa"], ["v", "speed", "m/s"], ["z", "height", "m"]],
    ex: "Water flows horizontally: $v_1 = 2$ m/s at $p_1$, and $v_2 = 5.56$ m/s where the pipe narrows. $p_1 - p_2 = \\tfrac12\\cdot 1000\\cdot(5.56^2 - 2^2) \\approx 13.4$ kPa.",
    tip: "Bernoulli only holds with no losses and no pump between the points – add such terms separately if they are present." } },
{ id: "torricelli",
  fig: `<svg viewBox="0 0 240 140"><rect x="40" y="20" width="90" height="80" class="d"/><path d="M40 30H130" class="dash"/><path d="M130 80h20" class="d"/><path d="M150 80H210" class="a"/><path d="M210 80l-12-5v10z" class="af"/><path d="M85 30V80" class="dim"/><text x="90" y="55">h</text></svg>`,
  nb: { t: "Torricellis lov",
    intro: "Torricellis lov følger direkte av Bernoulli: væske som strømmer ut av et lite hull et stykke under overflaten i en åpen tank, får samme fart som om den hadde falt fritt den høyden. Dette gjelder fordi trykket er atmosfærisk både ved overflaten og ved utstrømningen.",
    f: [["v = \\sqrt{2gh}", "utstrømningsfart fra en tank"]],
    legend: [["v", "utstrømningsfart", "m/s"], ["h", "høyde fra overflaten til hullet", "m"]],
    ex: "Et hull er $h = 3{,}0$ m under vannoverflaten i en åpen tank. $v = \\sqrt{2\\cdot 9{,}81\\cdot 3{,}0} \\approx 7{,}67$ m/s.",
    tip: "Torricellis lov gjelder bare når hullet er lite nok til at fallet i overflaten kan neglisjeres." },
  en: { t: "Torricelli's law",
    intro: "Torricelli's law follows directly from Bernoulli: fluid flowing out of a small hole some distance below the surface of an open tank reaches the same speed as if it had fallen freely that height. This holds because the pressure is atmospheric both at the surface and at the outlet.",
    f: [["v = \\sqrt{2gh}", "outflow speed from a tank"]],
    legend: [["v", "outflow speed", "m/s"], ["h", "height from the surface to the hole", "m"]],
    ex: "A hole is $h = 3.0$ m below the water surface in an open tank. $v = \\sqrt{2\\cdot 9.81\\cdot 3.0} \\approx 7.67$ m/s.",
    tip: "Torricelli's law only holds when the hole is small enough that the drop in the surface level can be neglected." } },
{ id: "pitotror",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 70H150" class="a"/><path d="M150 70l-12-5v10z" class="af"/><path d="M150 40V100" class="d"/><path d="M150 40h40v15h-40z" class="d"/><path d="M150 85h40v15h-40z" class="d"/><text x="60" y="60">v</text><text x="160" y="52">p₀</text><text x="160" y="98">p</text></svg>`,
  nb: { t: "Pitotrør",
    intro: "Et pitotrør måler farten i en strøm ved å bremse fluidet til ro i en liten åpning og sammenligne stagnasjonstrykket med det statiske trykket like ved. Forskjellen mellom dem er det dynamiske trykket, som Bernoulli knytter direkte til farten.",
    f: [["p_0 = p + \\tfrac12\\rho v^2", "stagnasjonstrykk"], ["v = \\sqrt{\\dfrac{2\\Delta p}{\\rho}}", "fart fra trykkforskjellen i et pitotrør"]],
    legend: [["p_0", "stagnasjonstrykk", "Pa"], ["\\Delta p", "trykkforskjell (dynamisk trykk)", "Pa"]],
    ex: "Et pitotrør i luft ($\\rho = 1{,}2$ kg/m³) måler $\\Delta p = 250$ Pa. $v = \\sqrt{2\\cdot 250/1{,}2} \\approx 20{,}4$ m/s.",
    tip: "Stagnasjonstrykket er alltid det høyeste trykket langs en strømlinje, siden all kinetisk energi der er omgjort til trykk." },
  en: { t: "Pitot tube",
    intro: "A Pitot tube measures the speed in a flow by bringing the fluid to rest in a small opening and comparing the stagnation pressure with the static pressure nearby. The difference between them is the dynamic pressure, which Bernoulli links directly to the speed.",
    f: [["p_0 = p + \\tfrac12\\rho v^2", "stagnation pressure"], ["v = \\sqrt{\\dfrac{2\\Delta p}{\\rho}}", "speed from the pressure difference in a Pitot tube"]],
    legend: [["p_0", "stagnation pressure", "Pa"], ["\\Delta p", "pressure difference (dynamic pressure)", "Pa"]],
    ex: "A Pitot tube in air ($\\rho = 1.2$ kg/m³) measures $\\Delta p = 250$ Pa. $v = \\sqrt{2\\cdot 250/1.2} \\approx 20.4$ m/s.",
    tip: "The stagnation pressure is always the highest pressure along a streamline, since all the kinetic energy there has converted to pressure." } }
]);

// ================= FLUID – enhet 2: Rørstrømning og dimensjonsløse tall =================
TOPICS("FLUID", 2, [
{ id: "reynoldstall",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 70H110" class="d"/><path d="M20 60H110M20 80H110" class="dim"/><path d="M130 40Q150 60 130 80T170 100T130 110" class="d"/><text x="55" y="50">L</text><text x="145" y="30">T</text></svg>`,
  nb: { t: "Reynoldstall",
    intro: "Reynoldstallet er et dimensjonsløst tall som forteller om strømningen er rolig og lagdelt (laminær) eller kaotisk med virvler (turbulent). Det uttrykker forholdet mellom treghetskrefter og viskøse krefter i fluidet, og bestemmer hvilken formel du bruker for friksjonsfaktoren.",
    f: [["Re = \\dfrac{\\rho vD}{\\mu}", "Reynoldstall i et rør"]],
    legend: [["\\mu", "dynamisk viskositet", "Pa·s"], ["D", "rørdiameter", "m"], ["Re", "Reynoldstall", ""]],
    ex: "Vann ($\\rho = 1000$ kg/m³, $\\mu = 10^{-3}$ Pa·s) strømmer med $v = 1{,}2$ m/s i et rør med $D = 40$ mm. $Re = 1000\\cdot 1{,}2\\cdot 0{,}04/10^{-3} = 48\\,000$.",
    tip: "$Re$ under ca. 2300 er laminær strømning, over ca. 4000 er turbulent, med et overgangsområde imellom." },
  en: { t: "Reynolds number",
    intro: "The Reynolds number is a dimensionless number that tells you whether a flow is smooth and layered (laminar) or chaotic with eddies (turbulent). It expresses the ratio of inertial to viscous forces in the fluid, and determines which formula you use for the friction factor.",
    f: [["Re = \\dfrac{\\rho vD}{\\mu}", "Reynolds number in a pipe"]],
    legend: [["\\mu", "dynamic viscosity", "Pa·s"], ["D", "pipe diameter", "m"], ["Re", "Reynolds number", ""]],
    ex: "Water ($\\rho = 1000$ kg/m³, $\\mu = 10^{-3}$ Pa·s) flows at $v = 1.2$ m/s in a pipe with $D = 40$ mm. $Re = 1000\\cdot 1.2\\cdot 0.04/10^{-3} = 48{,}000$.",
    tip: "$Re$ below about 2300 is laminar flow, above about 4000 is turbulent, with a transitional range in between." } },
{ id: "darcy-weisbach",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 70H210" class="b"/><path d="M40 60V80M100 60V80M160 60V80" class="dim"/><path d="M30 100H210" class="dim"/><text x="115" y="118">L</text></svg>`,
  nb: { t: "Darcy–Weisbachs ligning",
    intro: "Friksjon mellom fluidet og rørveggen gir et trykktap langs røret, som avhenger av lengden, diameteren, farten og en friksjonsfaktor. Friksjonsfaktoren har en enkel formel for laminær strømning, mens den for turbulent strømning må finnes fra tabeller eller diagrammer.",
    f: [["h_f = f\\dfrac{L}{D}\\dfrac{v^2}{2g}", "friksjonstap, Darcy–Weisbach"], ["f = \\dfrac{64}{Re}", "friksjonsfaktor, laminær strømning"]],
    legend: [["h_f", "friksjonstap", "m"], ["f", "friksjonsfaktor", ""], ["L", "rørlengde", "m"]],
    ex: "Vann strømmer med $v = 1{,}5$ m/s i et rør med $D = 30$ mm og $L = 20$ m, med $f = 0{,}027$. $h_f = 0{,}027\\cdot\\dfrac{20}{0{,}03}\\cdot\\dfrac{1{,}5^2}{2\\cdot 9{,}81} \\approx 2{,}06$ m.",
    tip: "$f = 64/Re$ gjelder bare laminær strømning – for turbulent strømning må $f$ finnes fra Moody-diagrammet eller en oppgitt verdi." },
  en: { t: "Darcy–Weisbach equation",
    intro: "Friction between the fluid and the pipe wall causes a pressure loss along the pipe, which depends on the length, diameter, speed and a friction factor. The friction factor has a simple formula for laminar flow, while for turbulent flow it must be found from tables or charts.",
    f: [["h_f = f\\dfrac{L}{D}\\dfrac{v^2}{2g}", "friction loss, Darcy–Weisbach"], ["f = \\dfrac{64}{Re}", "friction factor, laminar flow"]],
    legend: [["h_f", "friction loss", "m"], ["f", "friction factor", ""], ["L", "pipe length", "m"]],
    ex: "Water flows at $v = 1.5$ m/s in a pipe with $D = 30$ mm and $L = 20$ m, with $f = 0.027$. $h_f = 0.027\\cdot\\dfrac{20}{0.03}\\cdot\\dfrac{1.5^2}{2\\cdot 9.81} \\approx 2.06$ m.",
    tip: "$f = 64/Re$ only applies to laminar flow – for turbulent flow $f$ must come from the Moody chart or a given value." } },
{ id: "singulaertap",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 70H100" class="d"/><path d="M100 70l30-20h30l30 20" class="d"/><path d="M160 70H220" class="d"/><path d="M120 40h20v20h-20z" class="fill"/></svg>`,
  nb: { t: "Singulærtap",
    intro: "I tillegg til friksjon langs selve røret gir ventiler, bend og innsnevringer et ekstra trykktap, kalt singulærtap eller lokaltap. Tapet er proporsjonalt med det dynamiske trykket og en tapskoeffisient som avhenger av komponentens geometri, gitt i tabeller.",
    f: [["h_{lok} = K\\dfrac{v^2}{2g}", "singulærtap"]],
    legend: [["K", "tapskoeffisient (fra tabell)", ""], ["v", "fart i røret", "m/s"]],
    ex: "En ventil har $K = 2{,}0$ og farten i røret er $v = 1{,}8$ m/s. $h_{lok} = 2{,}0\\cdot 1{,}8^2/(2\\cdot 9{,}81) \\approx 0{,}330$ m.",
    tip: "Ved mange komponenter legger du sammen alle singulærtapene og friksjonstapet før du regner ut total pumpeeffekt." },
  en: { t: "Minor losses",
    intro: "In addition to friction along the pipe itself, valves, bends and constrictions cause an extra pressure loss, called a minor or local loss. The loss is proportional to the dynamic pressure and a loss coefficient that depends on the component's geometry, given in tables.",
    f: [["h_{minor} = K\\dfrac{v^2}{2g}", "minor loss"]],
    legend: [["K", "loss coefficient (from a table)", ""], ["v", "speed in the pipe", "m/s"]],
    ex: "A valve has $K = 2.0$ and the speed in the pipe is $v = 1.8$ m/s. $h_{minor} = 2.0\\cdot 1.8^2/(2\\cdot 9.81) \\approx 0.330$ m.",
    tip: "With many components, add up all the minor losses and the friction loss before computing the total pump power." } },
{ id: "pumpeeffekt",
  nb: { t: "Pumpeeffekt",
    intro: "En pumpe må levere nok energi til å overvinne det totale tapet i et rørsystem, både friksjonstap og singulærtap, samt eventuelt løfte fluidet i høyden. Den hydrauliske effekten regnes ut fra det totale tapet uttrykt i meter væskesøyle, tettheten og volumstrømmen.",
    f: [["P = \\rho gQh_f", "hydraulisk pumpeeffekt for å overvinne et tap $h_f$"]],
    legend: [["P", "hydraulisk pumpeeffekt", "W"], ["Q", "volumstrøm", "m³/s"], ["h_f", "totalt tap", "m"]],
    ex: "En pumpe leverer $Q = 8{,}0$ L/s vann mot et totalt tap på $h_f = 3{,}5$ m. $P = 1000\\cdot 9{,}81\\cdot 0{,}0080\\cdot 3{,}5 \\approx 275$ W.",
    tip: "Volumstrømmen må være i m³/s (del L/s på 1000) før den settes inn i $P = \\rho gQh_f$." },
  en: { t: "Pump power",
    intro: "A pump must supply enough energy to overcome the total loss in a piping system, both friction loss and minor losses, as well as any lift in elevation. The hydraulic power is computed from the total loss expressed in meters of fluid column, the density and the volumetric flow rate.",
    f: [["P = \\rho gQh_f", "hydraulic pump power to overcome a loss $h_f$"]],
    legend: [["P", "hydraulic pump power", "W"], ["Q", "volumetric flow rate", "m³/s"], ["h_f", "total loss", "m"]],
    ex: "A pump delivers $Q = 8.0$ L/s of water against a total loss of $h_f = 3.5$ m. $P = 1000\\cdot 9.81\\cdot 0.0080\\cdot 3.5 \\approx 275$ W.",
    tip: "The volumetric flow rate must be in m³/s (divide L/s by 1000) before substituting into $P = \\rho gQh_f$." } }
]);

// ================= VARME – enhet 0: Varmeledning =================
TOPICS("VARME", 0, [
{ id: "fouriers-lov",
  fig: `<svg viewBox="0 0 240 140"><rect x="90" y="30" width="40" height="80" class="fill"/><path d="M90 30h40v80h-40z" class="d"/><path d="M40 70H90" class="a"/><path d="M90 70l-12-5v10z" class="af"/><path d="M130 70H180" class="a"/><path d="M180 70l-12-5v10z" class="af"/><text x="95" y="25">T₁</text><text x="95" y="128">T₂</text></svg>`,
  nb: { t: "Fouriers lov",
    intro: "Varmeledning er transport av varme gjennom et stoff uten at stoffet selv beveger seg. Fouriers lov sier at varmestrømmen gjennom et plant sjikt er proporsjonal med temperaturforskjellen og arealet, og omvendt proporsjonal med tykkelsen. Varmeledningsevnen forteller hvor godt materialet leder varme.",
    f: [["\\dot Q = \\dfrac{kA\\Delta T}{L}", "varmestrøm gjennom et plant sjikt"]],
    legend: [["k", "varmeledningsevne", "W/(m·K)"], ["A", "areal vinkelrett på varmestrømmen", "m²"], ["L", "tykkelse", "m"]],
    ex: "Et sjikt med $L = 50$ mm, $k = 0{,}04$ W/(m·K) og $A = 10$ m² har $\\Delta T = 30$ K. $\\dot Q = 0{,}04\\cdot 10\\cdot 30/0{,}05 = 240$ W.",
    tip: "Ikke bland $k$ (varmeledningsevne, W/(m·K)) med $h$ (varmeovergangstall, W/(m²·K)) – de beskriver forskjellige mekanismer." },
  en: { t: "Fourier's law",
    intro: "Conduction is the transport of heat through a substance without the substance itself moving. Fourier's law says the heat flow through a plane layer is proportional to the temperature difference and the area, and inversely proportional to the thickness. The thermal conductivity tells you how well the material conducts heat.",
    f: [["\\dot Q = \\dfrac{kA\\Delta T}{L}", "heat flow through a plane layer"]],
    legend: [["k", "thermal conductivity", "W/(m·K)"], ["A", "area perpendicular to the heat flow", "m²"], ["L", "thickness", "m"]],
    ex: "A layer with $L = 50$ mm, $k = 0.04$ W/(m·K) and $A = 10$ m² has $\\Delta T = 30$ K. $\\dot Q = 0.04\\cdot 10\\cdot 30/0.05 = 240$ W.",
    tip: "Do not confuse $k$ (thermal conductivity, W/(m·K)) with $h$ (heat transfer coefficient, W/(m²·K)) – they describe different mechanisms." } },
{ id: "termisk-motstand-serie",
  fig: `<svg viewBox="0 0 240 140"><rect x="60" y="30" width="30" height="80" class="fill"/><rect x="90" y="30" width="60" height="80" class="fill"/><path d="M60 30v80M90 30v80M150 30v80" class="d"/><path d="M20 70H60" class="a"/><path d="M60 70l-12-5v10z" class="af"/><path d="M150 70H190" class="a"/><path d="M190 70l-12-5v10z" class="af"/></svg>`,
  nb: { t: "Termisk motstand i serie",
    intro: "Hvert sjikt en vegg er bygd opp av, har sin egen termiske motstand, akkurat som elektriske motstander i en krets. Motstandene legges sammen i serie for å finne den totale motstanden, og varmestrømmen er den samme gjennom hvert sjikt i stasjonær tilstand, selv om temperaturfallet er ulikt.",
    f: [["R = \\dfrac{L}{kA}", "termisk motstand, plant sjikt"], ["R_{tot} = \\sum R_i", "sjikt i serie"], ["\\dot Q = \\dfrac{\\Delta T}{R_{tot}}", "total varmestrøm"]],
    legend: [["R", "termisk motstand", "K/W"], ["R_{tot}", "total motstand", "K/W"]],
    ex: "To sjikt har $R_1 = 0{,}5$ K/W og $R_2 = 1{,}5$ K/W. $R_{tot} = 2{,}0$ K/W. Med $\\Delta T = 40$ K blir $\\dot Q = 40/2{,}0 = 20$ W.",
    tip: "Legg sammen motstandene i serie akkurat som elektriske motstander: $R_{tot} = \\sum L_i/(k_iA)$." },
  en: { t: "Thermal resistance in series",
    intro: "Each layer a wall is built from has its own thermal resistance, exactly like electrical resistors in a circuit. The resistances add in series to find the total resistance, and the heat flow is the same through every layer at steady state, even though the temperature drop differs between them.",
    f: [["R = \\dfrac{L}{kA}", "thermal resistance, plane layer"], ["R_{tot} = \\sum R_i", "layers in series"], ["\\dot Q = \\dfrac{\\Delta T}{R_{tot}}", "total heat flow"]],
    legend: [["R", "thermal resistance", "K/W"], ["R_{tot}", "total resistance", "K/W"]],
    ex: "Two layers have $R_1 = 0.5$ K/W and $R_2 = 1.5$ K/W. $R_{tot} = 2.0$ K/W. With $\\Delta T = 40$ K, $\\dot Q = 40/2.0 = 20$ W.",
    tip: "Add resistances in series exactly like electrical resistors: $R_{tot} = \\sum L_i/(k_iA)$." } },
{ id: "sylindrisk-motstand",
  fig: `<svg viewBox="0 0 240 140"><circle cx="120" cy="75" r="50" class="d"/><circle cx="120" cy="75" r="25" class="d"/><path d="M120 75L145 75" class="dim"/><path d="M120 75L120 25" class="dim"/><text x="128" y="55">r₂</text><text x="128" y="80">r₁</text></svg>`,
  nb: { t: "Sylindrisk termisk motstand",
    intro: "For et rør med isolasjon er den termiske motstanden ikke lineær i tykkelsen som for en plan vegg, fordi arealet varmen går gjennom øker med radien utover. Motstanden avhenger derfor logaritmisk av forholdet mellom ytre og indre radius.",
    f: [["R = \\dfrac{\\ln(r_2/r_1)}{2\\pi kL}", "termisk motstand, sylindrisk sjikt"]],
    legend: [["r_1,\\ r_2", "indre/ytre radius", "m"], ["L", "rørlengde", "m"]],
    ex: "Isolasjon fra $r_1 = 40$ mm til $r_2 = 70$ mm, $k = 0{,}045$ W/(m·K), $L = 8$ m. $R = \\ln(70/40)/(2\\pi\\cdot 0{,}045\\cdot 8) \\approx 0{,}247$ K/W.",
    tip: "Bruk aldri den plane formelen $R = L/(kA)$ på et rør – bruk $\\ln(r_2/r_1)$-formelen i stedet." },
  en: { t: "Cylindrical thermal resistance",
    intro: "For an insulated pipe, the thermal resistance is not linear in the thickness as for a plane wall, because the area the heat passes through grows with the radius outward. The resistance therefore depends logarithmically on the ratio of the outer to the inner radius.",
    f: [["R = \\dfrac{\\ln(r_2/r_1)}{2\\pi kL}", "thermal resistance, cylindrical layer"]],
    legend: [["r_1,\\ r_2", "inner/outer radius", "m"], ["L", "pipe length", "m"]],
    ex: "Insulation from $r_1 = 40$ mm to $r_2 = 70$ mm, $k = 0.045$ W/(m·K), $L = 8$ m. $R = \\ln(70/40)/(2\\pi\\cdot 0.045\\cdot 8) \\approx 0.247$ K/W.",
    tip: "Never use the plane-wall formula $R = L/(kA)$ for a pipe – use the $\\ln(r_2/r_1)$ formula instead." } },
{ id: "u-verdi",
  nb: { t: "U-verdi",
    intro: "U-verdien samler den totale termiske motstanden til en konstruksjon i ett tall: varmetapet per kvadratmeter og grad temperaturforskjell. Lav U-verdi betyr god isolasjon. Byggeforskrifter stiller ofte krav til maks U-verdi for vegger, tak og vinduer.",
    f: [["U = \\dfrac{1}{R_{tot}A}", "U-verdi fra total motstand"], ["\\dot Q = UA\\Delta T", "varmetap fra U-verdien"]],
    legend: [["U", "U-verdi", "W/(m²·K)"], ["A", "areal", "m²"]],
    ex: "En vegg har $R_{tot}A = 3{,}5$ m²K/W. $U = 1/3{,}5 \\approx 0{,}286$ W/(m²·K). Med $A = 15$ m² og $\\Delta T = 30$ K: $\\dot Q \\approx 128{,}6$ W.",
    tip: "Jo lavere U-verdi, desto bedre isolasjon – motsatt av varmeledningsevnen $k$, der en høyere verdi betyr dårligere isolasjon." },
  en: { t: "U-value",
    intro: "The U-value collects a construction's total thermal resistance into a single number: the heat loss per square meter and degree of temperature difference. A low U-value means good insulation. Building codes often set requirements for the maximum U-value of walls, roofs and windows.",
    f: [["U = \\dfrac{1}{R_{tot}A}", "U-value from total resistance"], ["\\dot Q = UA\\Delta T", "heat loss from the U-value"]],
    legend: [["U", "U-value", "W/(m²·K)"], ["A", "area", "m²"]],
    ex: "A wall has $R_{tot}A = 3.5$ m²K/W. $U = 1/3.5 \\approx 0.286$ W/(m²·K). With $A = 15$ m² and $\\Delta T = 30$ K: $\\dot Q \\approx 128.6$ W.",
    tip: "The lower the U-value, the better the insulation – the opposite of the thermal conductivity $k$, where a higher value means worse insulation." } }
]);

// ================= VARME – enhet 1: Konveksjon =================
TOPICS("VARME", 1, [
{ id: "newtons-avkjolingslov",
  fig: `<svg viewBox="0 0 240 140"><rect x="40" y="30" width="30" height="80" class="fill"/><path d="M40 30h30v80h-30z" class="d"/><path d="M90 50H130M90 70H130M90 90H130" class="a"/><path d="M130 50l-10-4v8zM130 70l-10-4v8zM130 90l-10-4v8z" class="af"/><text x="45" y="25">Tₛ</text><text x="180" y="70">T∞</text></svg>`,
  nb: { t: "Newtons avkjølingslov",
    intro: "Konveksjon er varmeoverføring mellom en overflate og et fluid som strømmer forbi. Newtons avkjølingslov sier at varmestrømmen er proporsjonal med temperaturforskjellen mellom overflaten og fluidet langt unna, gjennom varmeovergangstallet $h$, som avhenger av geometri, fluid og strømningsforhold.",
    f: [["\\dot Q = hA(T_s - T_\\infty)", "Newtons avkjølingslov"]],
    legend: [["h", "varmeovergangstall", "W/(m²·K)"], ["T_s", "overflatetemperatur", "K"], ["T_\\infty", "fluidtemperatur langt unna", "K"]],
    ex: "En plate med $A = 0{,}3$ m² og $h = 40$ W/(m²·K) har $45$ K temperaturforskjell mot luften. $\\dot Q = 40\\cdot 0{,}3\\cdot 45 = 540$ W.",
    tip: "$h$ er ikke en materialegenskap som $k$ – den avhenger av strømningen og må ofte finnes fra korrelasjoner eller oppgis." },
  en: { t: "Newton's law of cooling",
    intro: "Convection is heat transfer between a surface and a fluid flowing past it. Newton's law of cooling says the heat flow is proportional to the temperature difference between the surface and the fluid far away, through the heat transfer coefficient $h$, which depends on geometry, fluid and flow conditions.",
    f: [["\\dot Q = hA(T_s - T_\\infty)", "Newton's law of cooling"]],
    legend: [["h", "heat transfer coefficient", "W/(m²·K)"], ["T_s", "surface temperature", "K"], ["T_\\infty", "fluid temperature far away", "K"]],
    ex: "A plate with $A = 0.3$ m² and $h = 40$ W/(m²·K) has a $45$ K temperature difference from the air. $\\dot Q = 40\\cdot 0.3\\cdot 45 = 540$ W.",
    tip: "$h$ is not a material property like $k$ – it depends on the flow and often has to be found from correlations or given in the problem." } },
{ id: "konveksjonsmotstand-vegg",
  nb: { t: "Konveksjon i en sammensatt vegg",
    intro: "Konveksjon på overflaten av en vegg gir en termisk motstand akkurat som et ledningssjikt, og legges i serie med veggens egne sjikt. En realistisk vegg har derfor konveksjon på begge sider i tillegg til ledning gjennom materialene mellom dem.",
    f: [["R_{konv} = \\dfrac{1}{hA}", "termisk motstand ved konveksjon"], ["R_{tot} = \\dfrac{1}{h_iA} + \\sum\\dfrac{L_j}{k_jA} + \\dfrac{1}{h_uA}", "total motstand med konveksjon på begge sider"]],
    legend: [["h_i,\\ h_u", "varmeovergangstall innvendig/utvendig", "W/(m²·K)"], ["R_{konv}", "konveksjonsmotstand", "K/W"]],
    ex: "En vegg har $h_i = 8$, $h_u = 25$ W/(m²·K) og isolasjon $L = 100$ mm, $k = 0{,}03$ W/(m·K). Per areal: $1/8 + 0{,}1/0{,}03 + 1/25 \\approx 3{,}50$ m²K/W.",
    tip: "Ikke glem konveksjonsmotstanden $1/(hA)$ på begge sider – den er ofte like viktig som selve isolasjonssjiktet." },
  en: { t: "Convection in a composite wall",
    intro: "Convection at the surface of a wall gives a thermal resistance just like a conduction layer, and is placed in series with the wall's own layers. A realistic wall therefore has convection on both sides in addition to conduction through the materials between them.",
    f: [["R_{conv} = \\dfrac{1}{hA}", "thermal resistance for convection"], ["R_{tot} = \\dfrac{1}{h_iA} + \\sum\\dfrac{L_j}{k_jA} + \\dfrac{1}{h_oA}", "total resistance with convection on both sides"]],
    legend: [["h_i,\\ h_o", "indoor/outdoor heat transfer coefficient", "W/(m²·K)"], ["R_{conv}", "convection resistance", "K/W"]],
    ex: "A wall has $h_i = 8$, $h_o = 25$ W/(m²·K) and insulation $L = 100$ mm, $k = 0.03$ W/(m·K). Per area: $1/8 + 0.1/0.03 + 1/25 \\approx 3.50$ m²K/W.",
    tip: "Do not forget the convection resistance $1/(hA)$ on both sides – it is often just as important as the insulation layer itself." } },
{ id: "biottall",
  fig: `<svg viewBox="0 0 240 140"><circle cx="120" cy="75" r="45" class="fill"/><path d="M120 30V120" class="dim"/><text x="60" y="40">k</text><text x="175" y="40">h</text></svg>`,
  nb: { t: "Biottallet",
    intro: "Biottallet sammenligner motstanden mot ledning inni et legeme med motstanden mot konveksjon på overflaten. Er Biottallet lite, jevner ledningen inni legemet ut temperaturen raskt nok til at hele legemet kan regnes å ha én felles temperatur, kalt lumped capacitance.",
    f: [["Bi = \\dfrac{hL_c}{k}", "Biottall, $L_c$ = karakteristisk lengde"], ["Bi < 0{,}1", "lumped capacitance kan brukes"]],
    legend: [["Bi", "Biottall", ""], ["L_c", "karakteristisk lengde (V/A)", "m"]],
    ex: "En plate har $L_c = 8$ mm, $k = 60$ W/(m·K) og kjøles med $h = 40$ W/(m²·K). $Bi = 40\\cdot 0{,}008/60 \\approx 0{,}0053$, godt under $0{,}1$.",
    tip: "Sjekk alltid Biottallet før du bruker lumped capacitance – ellers kan temperaturen variere merkbart inni legemet." },
  en: { t: "The Biot number",
    intro: "The Biot number compares the resistance to conduction inside a body with the resistance to convection at its surface. When the Biot number is small, conduction inside the body evens out the temperature fast enough that the whole body can be treated as having one common temperature, called lumped capacitance.",
    f: [["Bi = \\dfrac{hL_c}{k}", "Biot number, $L_c$ = characteristic length"], ["Bi < 0.1", "lumped capacitance can be used"]],
    legend: [["Bi", "Biot number", ""], ["L_c", "characteristic length (V/A)", "m"]],
    ex: "A plate has $L_c = 8$ mm, $k = 60$ W/(m·K) and is cooled with $h = 40$ W/(m²·K). $Bi = 40\\cdot 0.008/60 \\approx 0.0053$, well below $0.1$.",
    tip: "Always check the Biot number before using lumped capacitance – otherwise the temperature can vary noticeably inside the body." } },
{ id: "tvungen-naturlig-konveksjon",
  nb: { t: "Tvungen og naturlig konveksjon",
    intro: "Ved tvungen konveksjon drives fluidet av en vifte eller pumpe, mens naturlig konveksjon drives av oppdrift fra temperaturforskjeller alene. Tvungen konveksjon gir vanligvis mye høyere $h$-verdier fordi en raskere strøm gjør grensesjiktet langs overflaten tynnere, slik at varmen ledes raskere ut i fluidet.",
    f: [["Nu = \\dfrac{hL}{k}", "Nusselttall, forholdet mellom konvektiv og konduktiv varmetransport"]],
    legend: [["Nu", "Nusselttall", ""], ["L", "karakteristisk lengde", "m"]],
    ex: "Naturlig konveksjon i luft gir typisk $h \\approx 2$–$25$ W/(m²·K), mens tvungen konveksjon i luft kan gi $h \\approx 10$–$200$ W/(m²·K).",
    tip: "En høyere fart gir et tynnere grensesjikt og dermed en høyere $h$ – dette gjelder for tvungen, ikke naturlig, konveksjon." },
  en: { t: "Forced and natural convection",
    intro: "In forced convection the fluid is driven by a fan or pump, while natural convection is driven by buoyancy from temperature differences alone. Forced convection usually gives much higher $h$ values because a faster flow makes the boundary layer along the surface thinner, so heat is conducted away into the fluid faster.",
    f: [["Nu = \\dfrac{hL}{k}", "Nusselt number, the ratio of convective to conductive heat transport"]],
    legend: [["Nu", "Nusselt number", ""], ["L", "characteristic length", "m"]],
    ex: "Natural convection in air typically gives $h \\approx 2$–$25$ W/(m²·K), while forced convection in air can give $h \\approx 10$–$200$ W/(m²·K).",
    tip: "A higher speed gives a thinner boundary layer and hence a higher $h$ – this applies to forced, not natural, convection." } }
]);

// ================= VARME – enhet 2: Stråling og transient varme =================
TOPICS("VARME", 2, [
{ id: "stefan-boltzmann",
  fig: `<svg viewBox="0 0 240 140"><circle cx="120" cy="75" r="35" class="fill"/><path d="M120 40V20M155 55L172 42M85 55L68 42M155 95L172 108M85 95L68 108" class="a"/><path d="M120 20l-6 10h12zM172 42l-4 13 12-6zM68 42l4 13-12-6zM172 108l-13-3 6 12zM68 108l13-3-6 12z" class="af"/></svg>`,
  nb: { t: "Stefan–Boltzmanns lov",
    intro: "Alle legemer med temperatur over det absolutte nullpunkt stråler ut energi som elektromagnetiske bølger, og dette er den eneste varmetransporten som fungerer i vakuum. Utstrålt effekt vokser med fjerde potens av den absolutte temperaturen, så selv en liten temperaturøkning gir en stor økning i strålingstapet.",
    f: [["\\dot Q_{ut} = \\varepsilon\\sigma AT^4", "utstrålt effekt fra en gråflate, $\\sigma = 5{,}67\\cdot 10^{-8}$ W/(m²K⁴)"], ["\\dot Q = \\varepsilon\\sigma A(T^4 - T_{omg}^4)", "netto strålingstap mot omgivelsene"]],
    legend: [["\\varepsilon", "emissivitet (0–1)", ""], ["\\sigma", "Stefan–Boltzmanns konstant", "W/(m²K⁴)"], ["T", "absolutt temperatur", "K"]],
    ex: "En overflate med $\\varepsilon = 0{,}8$, $A = 0{,}5$ m² holder $T = 500$ K i omgivelser på $T_{omg} = 300$ K. $\\dot Q = 0{,}8\\cdot 5{,}67\\cdot 10^{-8}\\cdot 0{,}5\\cdot(500^4-300^4) \\approx 1090$ W.",
    tip: "Regn alltid $T$ i kelvin i Stefan–Boltzmanns lov – $T^4$ er svært følsom for feil enhet." },
  en: { t: "Stefan–Boltzmann's law",
    intro: "Every body with a temperature above absolute zero radiates energy as electromagnetic waves, and this is the only form of heat transport that works in a vacuum. The power radiated grows with the fourth power of the absolute temperature, so even a small temperature rise gives a large increase in radiative loss.",
    f: [["\\dot Q_{out} = \\varepsilon\\sigma AT^4", "power radiated from a gray surface, $\\sigma = 5.67\\cdot 10^{-8}$ W/(m²K⁴)"], ["\\dot Q = \\varepsilon\\sigma A(T^4 - T_{surr}^4)", "net radiative loss to the surroundings"]],
    legend: [["\\varepsilon", "emissivity (0–1)", ""], ["\\sigma", "Stefan–Boltzmann constant", "W/(m²K⁴)"], ["T", "absolute temperature", "K"]],
    ex: "A surface with $\\varepsilon = 0.8$, $A = 0.5$ m² is at $T = 500$ K in surroundings at $T_{surr} = 300$ K. $\\dot Q = 0.8\\cdot 5.67\\cdot 10^{-8}\\cdot 0.5\\cdot(500^4-300^4) \\approx 1090$ W.",
    tip: "Always use $T$ in kelvin in Stefan–Boltzmann's law – $T^4$ is very sensitive to a wrong unit." } },
{ id: "emissivitet-kirchhoff",
  nb: { t: "Emissivitet og Kirchhoffs lov",
    intro: "Emissiviteten forteller hvor godt en flate stråler sammenlignet med et svart legeme, som har $\\varepsilon = 1$. Blanke, polerte metaller stråler dårlig og har lav emissivitet, mens matte, mørke flater stråler godt. Kirchhoffs lov sier at en god stråler også er en god absorbent.",
    f: [["\\alpha = \\varepsilon", "Kirchhoffs lov, gråflate i termisk likevekt"]],
    legend: [["\\varepsilon", "emissivitet", ""], ["\\alpha", "absorpsjonsevne", ""]],
    ex: "To like kuler ved samme temperatur, en svartmalt ($\\varepsilon \\approx 0{,}9$) og en blank ($\\varepsilon \\approx 0{,}1$), stråler svært ulikt: den svarte taper omtrent ni ganger så mye varme ved stråling.",
    tip: "Ikke anta samme emissivitet for alle flater – blanke flater kan ha $\\varepsilon$ under 0,1, mens matte flater ofte har $\\varepsilon$ over 0,9." },
  en: { t: "Emissivity and Kirchhoff's law",
    intro: "The emissivity tells you how well a surface radiates compared with a black body, which has $\\varepsilon = 1$. Shiny, polished metals radiate poorly and have low emissivity, while matte, dark surfaces radiate well. Kirchhoff's law says a good radiator is also a good absorber.",
    f: [["\\alpha = \\varepsilon", "Kirchhoff's law, gray surface in thermal equilibrium"]],
    legend: [["\\varepsilon", "emissivity", ""], ["\\alpha", "absorptivity", ""]],
    ex: "Two identical spheres at the same temperature, one painted black ($\\varepsilon \\approx 0.9$) and one shiny ($\\varepsilon \\approx 0.1$), radiate very differently: the black one loses about nine times as much heat by radiation.",
    tip: "Do not assume the same emissivity for every surface – shiny surfaces can have $\\varepsilon$ below 0.1, while matte surfaces often have $\\varepsilon$ above 0.9." } },
{ id: "kombinert-konveksjon-straling",
  nb: { t: "Kombinert konveksjon og stråling",
    intro: "En varm overflate i luft taper som regel varme gjennom både konveksjon og stråling samtidig, og de to bidragene må legges sammen for å finne det totale varmetapet. Ved lave temperaturforskjeller dominerer ofte konveksjon, mens strålingen blir stadig viktigere ved høyere temperaturer på grunn av $T^4$-avhengigheten.",
    f: [["\\dot Q_{tot} = hA(T_s-T_\\infty) + \\varepsilon\\sigma A(T_s^4-T_{omg}^4)", "kombinert varmetap fra samme overflate"]],
    legend: [["h", "varmeovergangstall", "W/(m²·K)"], ["\\varepsilon", "emissivitet", ""]],
    ex: "En rørflate med $A = 1{,}0$ m² gir $\\dot Q_{konv} = 300$ W ved konveksjon og $\\dot Q_{str} = 150$ W ved stråling. Totalt varmetap: $\\dot Q_{tot} = 300+150 = 450$ W.",
    tip: "Ikke tro at konveksjon og stråling utelukker hverandre – fra en varm overflate i luft skjer som regel begge samtidig." },
  en: { t: "Combined convection and radiation",
    intro: "A hot surface in air usually loses heat through both convection and radiation at once, and the two contributions must be added to find the total heat loss. At low temperature differences convection often dominates, while radiation becomes increasingly important at higher temperatures because of its $T^4$ dependence.",
    f: [["\\dot Q_{tot} = hA(T_s-T_\\infty) + \\varepsilon\\sigma A(T_s^4-T_{surr}^4)", "combined heat loss from the same surface"]],
    legend: [["h", "heat transfer coefficient", "W/(m²·K)"], ["\\varepsilon", "emissivity", ""]],
    ex: "A pipe surface with $A = 1.0$ m² gives $\\dot Q_{conv} = 300$ W by convection and $\\dot Q_{rad} = 150$ W by radiation. Total heat loss: $\\dot Q_{tot} = 300+150 = 450$ W.",
    tip: "Do not assume convection and radiation are mutually exclusive – from a hot surface in air, both usually happen at once." } },
{ id: "transient-avkjoling",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 30H210" class="dim"/><path d="M30 120H210" class="dim"/><path d="M30 30Q60 100 210 118" class="d"/><text x="10" y="35">T₀</text><text x="10" y="125">T∞</text></svg>`,
  nb: { t: "Transient avkjøling",
    intro: "Når Biottallet er lite, følger et legemes temperatur en eksponentiell tilnærming mot omgivelsestemperaturen over tid, styrt av en tidskonstant som avhenger av masse, varmekapasitet, varmeovergangstall og areal. Formelen kan snus for å finne tiden det tar å nå en gitt temperatur.",
    f: [["T(t) - T_\\infty = (T_0 - T_\\infty)e^{-t/\\tau}", "lumped capacitance, transient temperatur"], ["\\tau = \\dfrac{\\rho Vc}{hA}", "tidskonstant"], ["t = -\\tau\\ln\\!\\left(\\dfrac{T-T_\\infty}{T_0-T_\\infty}\\right)", "tid til gitt temperatur"]],
    legend: [["\\tau", "tidskonstant", "s"], ["T_0", "starttemperatur", "K"], ["T_\\infty", "omgivelsestemperatur", "K"]],
    ex: "Et legeme med $\\tau = 90$ s avkjøles fra $260$ °C i luft på $22$ °C. Tid til $60$ °C: $t = -90\\ln(38/238) \\approx 165$ s.",
    tip: "°C kan brukes direkte i differansene $T-T_\\infty$ i den transiente formelen, siden $273{,}15$ kanselleres i subtraksjonen." },
  en: { t: "Transient cooling",
    intro: "When the Biot number is small, a body's temperature follows an exponential approach toward the surrounding temperature over time, governed by a time constant that depends on mass, heat capacity, heat transfer coefficient and area. The formula can be inverted to find the time needed to reach a given temperature.",
    f: [["T(t) - T_\\infty = (T_0 - T_\\infty)e^{-t/\\tau}", "lumped capacitance, transient temperature"], ["\\tau = \\dfrac{\\rho Vc}{hA}", "time constant"], ["t = -\\tau\\ln\\!\\left(\\dfrac{T-T_\\infty}{T_0-T_\\infty}\\right)", "time to a given temperature"]],
    legend: [["\\tau", "time constant", "s"], ["T_0", "initial temperature", "K"], ["T_\\infty", "surrounding temperature", "K"]],
    ex: "A body with $\\tau = 90$ s cools from $260$ °C in air at $22$ °C. Time to reach $60$ °C: $t = -90\\ln(38/238) \\approx 165$ s.",
    tip: "°C can be used directly in the differences $T-T_\\infty$ in the transient formula, since the $273.15$ cancels in the subtraction." } }
]);
